// Finds two numbers in a vector that sum to a target value
struct TwoSumResult {
    size_t firstIndex;
    size_t secondIndex;
    bool found;
};

TwoSumResult findTwoSum(const vector<int>& numbers, int target) {
    unordered_map<int, size_t> seenNumbers;

    for (size_t currentIndex = 0; currentIndex < numbers.size(); ++currentIndex) {
        int complement = target - numbers[currentIndex];

        auto it = seenNumbers.find(complement);
        if (it != seenNumbers.end()) {
            return TwoSumResult{it->second, currentIndex, true};
        }

        seenNumbers[numbers[currentIndex]] = currentIndex;
    }

    return TwoSumResult{0, 0, false};
}

void printTwoSumResult(const TwoSumResult& result) {
    if (result.found) {
        cout << "Found at indices [" << result.firstIndex 
             << ", " << result.secondIndex << "]\n";
    } else {
        cout << "No two numbers sum to the target\n";
    }
}

int main() {
    vector<int> numbers = {2, 7, 11, 15};
    int target = 9;

    // Bad code call - what does proc do? Return? Print?
    // proc(numbers, target);  // Unclear

    // Clean code call - self-documenting
    auto result = findTwoSum(numbers, target);
    printTwoSumResult(result);

    return 0;
}

