// CLEAN: Each level of abstraction in its own function
class UserRepository {
public:
    bool usernameExists(const string& username) {
        ifstream db("users.db");
        string line;
        while (getline(db, line)) {
            if (line.find(username) == 0) {  // username at start
                return true;
            }
        }
        return false;
    }

    void saveUser(const string& username, const string& passwordHash, const string& email) {
        ofstream out("users.db", ios::app);
        out << username << ":" << passwordHash << ":" << email << "\n";
    }
};

class PasswordHasher {
public:
    string hash(const string& password) {
        size_t hashValue = 0;
        for (char c : password) {
            hashValue = hashValue * 31 + c;
        }
        return to_string(hashValue);
    }
};

class EmailService {
public:
    void sendWelcomeEmail(const string& email) {
        cout << "[EmailService] Welcome email sent to " << email << "\n";
    }
};

struct RegistrationRequest {
    string username;
    string password;
    string email;

    bool isValid() const {
        return !username.empty() && !password.empty() && !email.empty();
    }
};

// HIGH LEVEL: Business logic, single abstraction level
class RegistrationService {
    UserRepository& userRepo;
    PasswordHasher& hasher;
    EmailService& emailService;

public:
    RegistrationService(UserRepository& repo, PasswordHasher& hash, EmailService& email)
        : userRepo(repo), hasher(hash), emailService(email) {}

    void registerUser(const RegistrationRequest& request) {
        validateRequest(request);
        ensureUsernameAvailable(request.username);

        auto passwordHash = hasher.hash(request.password);
        userRepo.saveUser(request.username, passwordHash, request.email);

        emailService.sendWelcomeEmail(request.email);
    }

private:
    void validateRequest(const RegistrationRequest& request) {
        if (!request.isValid()) {
            throw invalid_argument("All fields are required");
        }
    }

    void ensureUsernameAvailable(const string& username) {
        if (userRepo.usernameExists(username)) {
            throw runtime_error("Username already exists: " + username);
        }
    }
};

