**Flag arguments** are boolean parameters that change function behavior. They are a code smell because they indicate the function does more than one thing.

```cpp
// BAD: Does two things depending on flag
void render(bool isForPrinter);

// CLEAN: Two focused functions
void renderForScreen();
void renderForPrinter();
```

**Side effects** are changes a function makes beyond its stated purpose. A function called `checkPassword` should not log the user in. A getter should not mutate state. Side effects are lies — they violate the principle of least astonishment.

**Command Query Separation**: A function should either:
• **Command**: Perform an action (mutate state, return void).
• **Query**: Return data (no side effects, pure function).

Never do both in the same function.

#include <bits/stdc++.h>
using namespace std;

// BAD: Flag argument - function does two things
class ReportGeneratorBad {
public:
    string generate(bool includeConfidential) {
        string report = "Sales Report\n";
        report += "Public Data: $100,000\n";

        if (includeConfidential) {  // Flag changes behavior
            report += "Confidential: $50,000\n";
            report += "Projections: +15%\n";
            logConfidentialAccess();  // Hidden side effect!
        }

        return report;
    }

private:
    void logConfidentialAccess() {
        cout << "[AUDIT] Confidential report accessed\n";
    }
};

// CLEAN: Separate functions, no flags, no hidden side effects
class ReportGenerator {
public:
    string generatePublicReport() const {
        return "Sales Report\nPublic Data: $100,000\n";
    }

    string generateConfidentialReport() const {
        return "Sales Report\nPublic Data: $100,000\n"
               "Confidential: $50,000\nProjections: +15%\n";
    }
};

class AuditLogger {
public:
    void logConfidentialAccess(const string& userId) {
        cout << "[AUDIT] User " << userId 
             << " accessed confidential report\n";
    }
};

// BAD: Query with side effect
class UserRepositoryBad {
    mutable int queryCount = 0;  // Hidden mutation!

public:
    bool exists(const string& username) const {
        queryCount++;  // Side effect in a query!
        // ... check database
        return false;
    }

    int getQueryCount() const { return queryCount; }
};

// CLEAN: Separate command and query
class UserRepository {
    int queryCount = 0;

public:
    // Query: pure, no side effects
    bool exists(const string& username) const {
        // ... check database
        return false;
    }

    // Command: explicit side effect
    void recordQuery() {
        queryCount++;
    }

    // Query: get the count
    int getQueryCount() const { return queryCount; }
};

int main() {
    cout << "=== Flag Arguments ===\n";
    ReportGenerator report;
    cout << report.generatePublicReport() << "\n";
    cout << report.generateConfidentialReport() << "\n";

    cout << "=== Command Query Separation ===\n";
    UserRepository repo;
    bool found = repo.exists("alice");  // Pure query
    repo.recordQuery();                  // Explicit command
    cout << "Queries: " << repo.getQueryCount() << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// BAD: Deep nesting, hard to follow
double calculateDiscountBad(const string& customerType, int years, double amount) {
    double discount = 0.0;
    if (amount > 100) {
        if (customerType == "premium") {
            if (years > 5) {
                discount = 0.25;
            } else {
                discount = 0.20;
            }
        } else if (customerType == "standard") {
            if (years > 3) {
                discount = 0.15;
            } else {
                discount = 0.10;
            }
        } else {
            discount = 0.05;
        }
    }
    return discount;
}

// CLEAN: Guard clauses + early returns
double calculateDiscount(const string& customerType, int years, double amount) {
    if (amount <= 100) {
        return 0.0;  // Guard clause
    }

    if (customerType == "premium") {
        return (years > 5) ? 0.25 : 0.20;
    }

    if (customerType == "standard") {
        return (years > 3) ? 0.15 : 0.10;
    }

    return 0.05;  // Default case
}

// Even cleaner: Replace conditional with polymorphism
class Customer {
public:
    virtual ~Customer() = default;
    virtual double getDiscountRate(int years) const = 0;
    virtual bool qualifiesForDiscount(double amount) const { return amount > 100; }
};

class PremiumCustomer : public Customer {
public:
    double getDiscountRate(int years) const override {
        return (years > 5) ? 0.25 : 0.20;
    }
};

class StandardCustomer : public Customer {
public:
    double getDiscountRate(int years) const override {
        return (years > 3) ? 0.15 : 0.10;
    }
};

class BasicCustomer : public Customer {
public:
    double getDiscountRate(int) const override {
        return 0.05;
    }
};

double calculateDiscountPolymorphic(const Customer& customer, int years, double amount) {
    if (!customer.qualifiesForDiscount(amount)) {
        return 0.0;
    }
    return customer.getDiscountRate(years);
}

int main() {
    cout << "=== Nested vs Guard Clauses ===\n";
    cout << "Premium, 6 years, $200: " 
         << calculateDiscount("premium", 6, 200) * 100 << "%\n";
    cout << "Standard, 2 years, $200: " 
         << calculateDiscount("standard", 2, 200) * 100 << "%\n";
    cout << "Basic, any years, $50: " 
         << calculateDiscount("basic", 10, 50) * 100 << "%\n";

    cout << "\n=== Polymorphic Approach ===\n";
    PremiumCustomer premium;
    StandardCustomer standard;
    BasicCustomer basic;

    cout << "Premium: " << calculateDiscountPolymorphic(premium, 6, 200) * 100 << "%\n";
    cout << "Standard: " << calculateDiscountPolymorphic(standard, 2, 200) * 100 << "%\n";
    cout << "Basic (low amount): " << calculateDiscountPolymorphic(basic, 10, 50) * 100 << "%\n";

    return 0;
}

