// === Implementation follows declaration order ===

HttpRequestHandler::HttpRequestHandler(const Router& router) : router_(router) {}

HttpResponse HttpRequestHandler::handleRequest(const HttpRequest& request) {
    if (!validateRequest(request)) {
        return formatErrorResponse(StatusCode::BAD_REQUEST, "Invalid request");
    }

    if (auto cached = checkCache(request)) {
        return *cached;
    }

    auto response = routeRequest(request);
    logRequest(request, response);
    return response;
}

void HttpRequestHandler::setTimeout(chrono::milliseconds timeout) {
    timeout_ = timeout;
}

void HttpRequestHandler::setMaxBodySize(size_t maxBytes) {
    maxBodySize_ = maxBytes;
}

bool HttpRequestHandler::validateRequest(const HttpRequest& request) const {
    return !request.path.empty() && request.method != HttpMethod::UNKNOWN;
}

optional<HttpResponse> HttpRequestHandler::checkCache(const HttpRequest& request) const {
    // Cache lookup implementation...
    return nullopt;
}

HttpResponse HttpRequestHandler::routeRequest(const HttpRequest& request) {
    auto handler = router_.findHandler(request.path);
    return handler(request);
}

HttpResponse HttpRequestHandler::formatErrorResponse(
    StatusCode code, const string& message) const {
    return HttpResponse{code, "application/json", 
                        "{\"error\":\"" + message + "\"}"};
}

string HttpRequestHandler::extractClientIp(const HttpRequest& request) const {
    auto forwarded = request.headers.get("X-Forwarded-For");
    return forwarded ? *forwarded : request.remoteAddress;
}

void HttpRequestHandler::logRequest(
    const HttpRequest& request, const HttpResponse& response) const {
    lock_guard<mutex> lock(logMutex_);
    cout << "[" << request.timestamp << "] " 
         << toString(request.method) << " " << request.path 
         << " -> " << static_cast<int>(response.statusCode) << "\n";
}

