namespace sales {

// Anonymous namespace for file-local helpers
namespace {
    constexpr auto MAX_RETRY_ATTEMPTS = 3;
    constexpr auto RETRY_DELAY_MS = 100;

    std::string generateTransactionId() {
        static std::atomic<uint64_t> counter{0};
        auto now = std::chrono::system_clock::now().time_since_epoch().count();
        return "TXN-" + std::to_string(now) + "-" + std::to_string(counter++);
    }

    bool isRetryableError(PaymentError error) {
        return error == PaymentError::NETWORK_TIMEOUT ||
               error == PaymentError::GATEWAY_BUSY;
    }
}

OrderProcessor::OrderProcessor(PaymentGateway& gateway, InventoryService& inventory)
    : gateway_(gateway), inventory_(inventory) {}

OrderProcessor::ProcessingResult OrderProcessor::processOrder(const Order& order) {
    if (!validateInventory(order)) {
        return ProcessingResult{false, "", {}};
    }

    auto transactionId = chargePayment(order);
    if (!transactionId) {
        return ProcessingResult{false, "", {}};
    }

    updateInventory(order);
    sendConfirmation(order, *transactionId);

    return ProcessingResult{true, *transactionId, std::chrono::system_clock::now()};
}

void OrderProcessor::cancelOrder(const std::string& transactionId) {
    gateway_.refund(transactionId);
    LOG_INFO << "Order cancelled: " << transactionId;
}

bool OrderProcessor::validateInventory(const Order& order) const {
    for (const auto& item : order.items()) {
        if (!inventory_.isAvailable(item.sku, item.quantity)) {
            return false;
        }
    }
    return true;
}

std::optional<std::string> OrderProcessor::chargePayment(const Order& order) {
    for (int attempt = 0; attempt < MAX_RETRY_ATTEMPTS; ++attempt) {
        auto result = gateway_.charge(order.total(), order.paymentMethod());
        if (result.success) {
            return result.transactionId;
        }
        if (!isRetryableError(result.error)) {
            return std::nullopt;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(RETRY_DELAY_MS));
    }
    return std::nullopt;
}

void OrderProcessor::updateInventory(const Order& order) {
    for (const auto& item : order.items()) {
        inventory_.reserve(item.sku, item.quantity);
    }
}

void OrderProcessor::sendConfirmation(const Order& order, const std::string& transactionId) {
    EmailService::send(order.customerEmail(), 
                       "Order Confirmed: " + transactionId,
                       generateConfirmationBody(order));
}

