void ShoppingCart::addItem(const string& sku, int quantity, double unitPrice) {
    auto it = find_if(items_.begin(), items_.end(),
                      [&sku](const auto& item) { return item.sku == sku; });
    if (it != items_.end()) {
        it->quantity += quantity;
    } else {
        items_.push_back({sku, quantity, unitPrice});
    }
}

double ShoppingCart::totalPrice() const {
    return calculateSubtotal() - calculateDiscount();
}

double ShoppingCart::calculateSubtotal() const {
    return transform_reduce(items_.begin(), items_.end(), 0.0, plus<>(),
                            [](const auto& item) {
                                return item.quantity * item.unitPrice;
