// CLEAN: Telling — account knows its own rules
enum class WithdrawalResult {
    SUCCESS,
    OVERDRAFT_WITH_FEE,
    INSUFFICIENT_FUNDS
};

class Account {
public:
    explicit Account(double initialBalance) : balance_(initialBalance) {}

    // Tell the account to withdraw; it decides if it's allowed
    WithdrawalResult withdraw(double amount) {
        if (balance_ >= amount) {
            balance_ -= amount;
            return WithdrawalResult::SUCCESS;
        }

        if (balance_ + overdraftLimit_ >= amount) {
            balance_ -= amount;
            overdraftUsed_ += (amount - balance_);
            return WithdrawalResult::OVERDRAFT_WITH_FEE;
        }

        return WithdrawalResult::INSUFFICIENT_FUNDS;
    }

    void deposit(double amount) {
        balance_ += amount;
        if (balance_ > 0) {
            overdraftUsed_ = 0;  // Reset overdraft tracking
        }
    }

    double getBalance() const { return balance_; }
    double getAvailableFunds() const { return balance_ + overdraftLimit_; }

private:
    double balance_;
    double overdraftLimit_ = 100.0;
    double overdraftUsed_ = 0.0;
};

void processWithdrawal(Account& account, double amount) {
    auto result = account.withdraw(amount);

    switch (result) {
        case WithdrawalResult::SUCCESS:
            cout << "Withdrawal of $" << amount << " successful. "
                 << "New balance: $" << account.getBalance() << "\n";
            break;
        case WithdrawalResult::OVERDRAFT_WITH_FEE:
            cout << "Withdrawal of $" << amount << " approved with overdraft. "
                 << "New balance: $" << account.getBalance() << "\n";
            break;
        case WithdrawalResult::INSUFFICIENT_FUNDS:
            cout << "Withdrawal of $" << amount << " declined. "
                 << "Available: $" << account.getAvailableFunds() << "\n";
            break;
    }
}

// Another example: Tell, Don't Ask with collections
class Team {
    vector<string> members_;
    string lead_;
public:
    void addMember(const string& name) {
        if (members_.empty()) {
            lead_ = name;  // First member becomes lead
        }
        members_.push_back(name);
    }

    void removeMember(const string& name) {
        members_.erase(remove(members_.begin(), members_.end(), name), members_.end());
        if (name == lead_ && !members_.empty()) {
            lead_ = members_.front();  // Reassign lead
        }
    }

    bool hasMember(const string& name) const {
        return find(members_.begin(), members_.end(), name) != members_.end();
    }

    const vector<string>& getMembers() const { return members_; }
    string getLead() const { return lead_; }
};

int main() {
    cout << "=== Tell, Don't Ask ===\n";
    Account account(500.0);

    processWithdrawal(account, 200.0);   // Success
    processWithdrawal(account, 350.0);   // Overdraft
    processWithdrawal(account, 100.0);   // Insufficient

    cout << "\n=== Team Management ===\n";
    Team team;
    team.addMember("Alice");
    team.addMember("Bob");
    team.addMember("Charlie");

    cout << "Lead: " << team.getLead() << "\n";
    cout << "Members: ";
    for (const auto& m : team.getMembers()) cout << m << " ";
    cout << "\n";

    team.removeMember("Alice");  // Lead removed, Bob becomes lead
    cout << "After removing Alice, lead: " << team.getLead() << "\n";

    return 0;
}

