// Good for: simple entities where CRUD is 90% of the logic
class BlogPost {
public:
    int id;
    string title;
    string content;
    string author;
    chrono::system_clock::time_point createdAt;
    bool isPublished;

    // Simple persistence methods
    void save(Database& db) {
        if (id == 0) {
            id = db.insert("posts", toJson());
        } else {
            db.update("posts", id, toJson());
        }
    }

    static optional<BlogPost> findById(Database& db, int postId) {
        auto row = db.queryOne("SELECT * FROM posts WHERE id = ?", postId);
        if (!row) return nullopt;
        return fromRow(*row);
    }

    static vector<BlogPost> findByAuthor(Database& db, const string& author) {
        auto rows = db.query("SELECT * FROM posts WHERE author = ?", author);
        vector<BlogPost> posts;
        for (const auto& row : rows) {
            posts.push_back(fromRow(row));
        }
        return posts;
    }

private:
    json toJson() const {
        return json{{"title", title}, {"content", content}, 
                    {"author", author}, {"is_published", isPublished}};
    }

    static BlogPost fromRow(const DatabaseRow& row) {
        BlogPost post;
        post.id = row.get<int>("id");
        post.title = row.get<string>("title");
        post.content = row.get<string>("content");
        post.author = row.get<string>("author");
        post.isPublished = row.get<bool>("is_published");
        return post;
    }
};

// === Rich Domain Model: Complex behavior separated from persistence ===
// Good for: complex business rules, invariants, state machines
class Order {
public:
    enum class Status { PENDING, CONFIRMED, SHIPPED, DELIVERED, CANCELLED };

    Order(string customerId, vector<OrderItem> items)
        : customerId_(move(customerId)), items_(move(items)), status_(Status::PENDING) {
        validateOrder();
    }

    // Business behavior, not just CRUD
    void confirm(const PaymentResult& payment) {
        if (status_ != Status::PENDING) {
            throw InvalidStateException("Can only confirm pending orders");
        }
        if (!payment.wasSuccessful()) {
            throw PaymentFailedException(payment.errorMessage());
        }

        payment_ = payment;
        status_ = Status::CONFIRMED;
        confirmedAt_ = chrono::system_clock::now();

        reserveInventory();
        sendConfirmationEmail();
    }

    void ship(const ShippingLabel& label) {
        if (status_ != Status::CONFIRMED) {
            throw InvalidStateException("Can only ship confirmed orders");
        }

        shippingLabel_ = label;
        status_ = Status::SHIPPED;
        shippedAt_ = chrono::system_clock::now();

        notifyCustomerOfShipment();
    }

    void cancel(const string& reason) {
        if (status_ == Status::SHIPPED || status_ == Status::DELIVERED) {
            throw InvalidStateException("Cannot cancel shipped or delivered orders");
        }

        status_ = Status::CANCELLED;
        cancellationReason_ = reason;

        if (payment_) {
            refundPayment();
        }
        releaseInventory();
    }

    // Queries
    double totalAmount() const {
        return transform_reduce(items_.begin(), items_.end(), 0.0, plus<>(),
                                [](const auto& item) { return item.totalPrice(); });
    }

    bool canBeCancelled() const {
        return status_ == Status::PENDING || status_ == Status::CONFIRMED;
    }

    Status getStatus() const { return status_; }
    string getCustomerId() const { return customerId_; }

private:
    void validateOrder() const {
        if (items_.empty()) {
            throw InvalidOrderException("Order must contain at least one item");
        }
        for (const auto& item : items_) {
            if (item.quantity <= 0) {
                throw InvalidOrderException("Item quantity must be positive");
            }
        }
    }

    void reserveInventory();
    void releaseInventory();
    void sendConfirmationEmail();
    void notifyCustomerOfShipment();
    void refundPayment();

    string customerId_;
    vector<OrderItem> items_;
    Status status_;
    optional<PaymentResult> payment_;
    optional<ShippingLabel> shippingLabel_;
    optional<chrono::system_clock::time_point> confirmedAt_;
    optional<chrono::system_clock::time_point> shippedAt_;
    optional<string> cancellationReason_;
};

