// === VALUE OBJECT: Money ===
// Immutable, defined by amount + currency
class Money {
    double amount_;
    string currency_;

public:
    Money(double amount, string currency)
        : amount_(amount), currency_(move(currency)) {
        if (amount_ < 0) {
            throw invalid_argument("Money amount cannot be negative");
        }
    }

    double amount() const { return amount_; }
    const string& currency() const { return currency_; }

    // Returns NEW Money — does not mutate
    Money add(const Money& other) const {
        if (currency_ != other.currency_) {
            throw invalid_argument("Cannot add different currencies");
        }
        return Money(amount_ + other.amount_, currency_);
    }

    Money subtract(const Money& other) const {
        if (currency_ != other.currency_) {
            throw invalid_argument("Cannot subtract different currencies");
        }
        return Money(amount_ - other.amount_, currency_);
    }

    Money multiply(double factor) const {
        return Money(amount_ * factor, currency_);
    }

    bool isZero() const { return amount_ == 0.0; }

    bool operator==(const Money& other) const {
        return amount_ == other.amount_ && currency_ == other.currency_;
    }

    bool operator!=(const Money& other) const {
        return !(*this == other);
    }

    string toString() const {
        ostringstream oss;
        oss << fixed << setprecision(2) << amount_ << " " << currency_;
        return oss.str();
    }
};

// === ENTITY: BankAccount ===
// Defined by account number, mutable state
class BankAccount {
    string accountNumber_;
    Money balance_;
    vector<string> transactionLog_;
    mutable mutex mutex_;  // For thread safety

public:
    BankAccount(string accountNumber, Money initialBalance)
        : accountNumber_(move(accountNumber)), balance_(move(initialBalance)) {}

    // Identity comparison — same account number = same entity
    bool operator==(const BankAccount& other) const {
        return accountNumber_ == other.accountNumber_;
    }

    const string& accountNumber() const { return accountNumber_; }

    Money balance() const {
        lock_guard<mutex> lock(mutex_);
        return balance_;
    }

    void deposit(const Money& amount) {
        if (amount.isZero()) return;

        lock_guard<mutex> lock(mutex_);
        balance_ = balance_.add(amount);
        transactionLog_.push_back("DEPOSIT: " + amount.toString());
    }

    void withdraw(const Money& amount) {
        lock_guard<mutex> lock(mutex_);
        if (amount.amount() > balance_.amount()) {
            throw runtime_error("Insufficient funds: " + balance_.toString());
        }
        balance_ = balance_.subtract(amount);
        transactionLog_.push_back("WITHDRAW: " + amount.toString());
    }

    void transferTo(BankAccount& recipient, const Money& amount) {
        // Lock both accounts to prevent deadlock
        lock(mutex_, recipient.mutex_);
        lock_guard<mutex> lock1(mutex_, adopt_lock);
        lock_guard<mutex> lock2(recipient.mutex_, adopt_lock);

        if (amount.amount() > balance_.amount()) {
            throw runtime_error("Insufficient funds for transfer");
        }

        balance_ = balance_.subtract(amount);
        recipient.balance_ = recipient.balance_.add(amount);

        transactionLog_.push_back("TRANSFER OUT: " + amount.toString() + 
                                   " to " + recipient.accountNumber_);
        recipient.transactionLog_.push_back("TRANSFER IN: " + amount.toString() + 
                                             " from " + accountNumber_);
    }

    vector<string> recentTransactions(size_t count) const {
        lock_guard<mutex> lock(mutex_);
        auto start = transactionLog_.size() > count 
                     ? transactionLog_.end() - count 
                     : transactionLog_.begin();
        return vector<string>(start, transactionLog_.end());
    }
};

// === Another Value Object: Color ===
struct Color {
    uint8_t r;
    uint8_t g;
    uint8_t b;
    uint8_t a = 255;

    static Color red()   { return Color{255, 0, 0}; }
    static Color green() { return Color{0, 255, 0}; }
    static Color blue()  { return Color{0, 0, 255}; }
    static Color white() { return Color{255, 255, 255}; }
    static Color black() { return Color{0, 0, 0}; }

    Color withAlpha(uint8_t newAlpha) const {
        return Color{r, g, b, newAlpha};
    }

    Color darken(double factor) const {
        return Color{
            static_cast<uint8_t>(r * (1 - factor)),
            static_cast<uint8_t>(g * (1 - factor)),
            static_cast<uint8_t>(b * (1 - factor)),
            a
        };
    }

    bool operator==(const Color& other) const {
        return r == other.r && g == other.g && b == other.b && a == other.a;
    }

    string toHex() const {
        ostringstream oss;
        oss << "#" << hex << setw(2) << setfill('0') << (int)r
            << setw(2) << (int)g << setw(2) << (int)b;
        if (a != 255) oss << setw(2) << (int)a;
        return oss.str();
    }
};

