// CLEAN: Exceptions for exceptional cases
class FileException : public runtime_error {
public:
    explicit FileException(const string& path)
        : runtime_error("Cannot open file: " + path), path_(path) {}
    const string& path() const { return path_; }
private:
    string path_;
};

class ParseException : public runtime_error {
    int line_;
public:
    ParseException(const string& msg, int line)
        : runtime_error(msg + " at line " + to_string(line)), line_(line) {}
    int line() const { return line_; }
};

Config readConfig(const string& path) {
    ifstream file(path);
    if (!file) {
        throw FileException(path);
    }

    Config config;
    string line;
    int lineNum = 0;
    while (getline(file, line)) {
        ++lineNum;
        if (!parseLine(line, config)) {
            throw ParseException("Invalid syntax", lineNum);
        }
    }

    return config;
}

