#include <bits/stdc++.h>
using namespace std;

// Design exceptions based on what callers need to handle differently
class NetworkException : public runtime_error {
public:
    using runtime_error::runtime_error;
};

class ConnectionTimeout : public NetworkException {
    chrono::milliseconds timeout_;
public:
    explicit ConnectionTimeout(chrono::milliseconds timeout)
        : NetworkException("Connection timed out after " + 
                           to_string(timeout.count()) + "ms"),
          timeout_(timeout) {}
    auto timeout() const { return timeout_; }
};

class ConnectionRefused : public NetworkException {
    string host_;
    int port_;
public:
    ConnectionRefused(const string& host, int port)
        : NetworkException("Connection refused: " + host + ":" + to_string(port)),
          host_(host), port_(port) {}
};

class DnsResolutionFailed : public NetworkException {
    string hostname_;
public:
    explicit DnsResolutionFailed(const string& hostname)
        : NetworkException("DNS resolution failed: " + hostname),
          hostname_(hostname) {}
};

class HttpException : public runtime_error {
    int statusCode_;
public:
    HttpException(int statusCode, const string& message)
        : runtime_error("HTTP " + to_string(statusCode) + ": " + message),
          statusCode_(statusCode) {}
    int statusCode() const { return statusCode_; }
    bool isClientError() const { return statusCode_ >= 400 && statusCode_ < 500; }
    bool isServerError() const { return statusCode_ >= 500; }
};

// HTTP client designed with error-first thinking
class HttpClient {
    chrono::milliseconds defaultTimeout_;
    int maxRetries_;

public:
    struct Response {
        int statusCode;
        map<string, string> headers;
        string body;
    };

    explicit HttpClient(chrono::milliseconds timeout = chrono::seconds(30))
        : defaultTimeout_(timeout), maxRetries_(3) {}

    // Caller needs to distinguish:
    // - Network issues (retry? fail?)
    // - 4xx errors (client bug, don't retry)
    // - 5xx errors (server issue, maybe retry)
    Response get(const string& url) {
        // Try-catch-first design: what errors can occur?
        // 1. DNS failure
        // 2. Connection refused
        // 3. Timeout
        // 4. HTTP error status

        auto host = extractHost(url);
        auto port = extractPort(url);

        for (int attempt = 0; attempt < maxRetries_; ++attempt) {
            try {
                auto connection = establishConnection(host, port);
                auto response = sendRequest(connection, "GET", url);

                if (response.statusCode >= 400) {
                    throw HttpException(response.statusCode, response.body);
                }

                return response;

            } catch (const ConnectionTimeout& e) {
                if (attempt < maxRetries_ - 1) {
                    auto delay = chrono::milliseconds(100 * (attempt + 1));
                    this_thread::sleep_for(delay);
                    continue;  // Retry
                }
                throw;  // Exhausted retries
            } catch (const ConnectionRefused&) {
                throw;  // Don't retry — service is down
            } catch (const DnsResolutionFailed&) {
                throw;  // Don't retry — bad URL
            }
        }

        throw logic_error("Unreachable: retries exhausted without exception");
    }

private:
    string extractHost(const string& url) {
        // Simplified parsing
        auto start = url.find("://");
        start = (start == string::npos) ? 0 : start + 3;
        auto end = url.find(':', start);
        if (end == string::npos) end = url.find('/', start);
        return url.substr(start, end - start);
    }

    int extractPort(const string& url) {
        auto hostEnd = url.find("://");
        hostEnd = (hostEnd == string::npos) ? 0 : hostEnd + 3;
        auto portStart = url.find(':', hostEnd);
        if (portStart == string::npos) return url.starts_with("https") ? 443 : 80;
        auto portEnd = url.find('/', portStart);
        return stoi(url.substr(portStart + 1, portEnd - portStart - 1));
    }

    // Simulated for demonstration
    struct Connection {};
    Connection establishConnection(const string& host, int port) {
        if (host == "timeout.example.com") {
            throw ConnectionTimeout(defaultTimeout_);
        }
        if (host == "refused.example.com") {
            throw ConnectionRefused(host, port);
        }
        if (host == "dnsfail.example.com") {
            throw DnsResolutionFailed(host);
        }
        return Connection{};
    }

    Response sendRequest(const Connection&, const string& method, const string& url) {
        if (url.find("/notfound") != string::npos) {
            return Response{404, {}, "Not Found"};
        }
        if (url.find("/error") != string::npos) {
            return Response{500, {}, "Internal Server Error"};
        }
        return Response{200, {{"Content-Type", "application/json"}}, "{\"status\":\"ok\"}"};
    }
};

// Call site designed around error handling needs
void fetchUserData(const string& apiUrl) {
    HttpClient client(chrono::seconds(10));

    try {
        auto response = client.get(apiUrl);
        auto user = parseJson(response.body);
        displayUser(user);

    } catch (const ConnectionTimeout& e) {
        // Retry logic already handled in client, but we might want to
        // show a "please try again later" message
        showError("The server is slow. Please try again. (" + string(e.what()) + ")");

    } catch (const ConnectionRefused& e) {
        // Service is down — notify ops team
        showError("Service temporarily unavailable.");
        alertOperations(e.what());

    } catch (const DnsResolutionFailed& e) {
        // Bad configuration — log for debugging
        logError("Configuration issue: " + string(e.what()));
        showError("Invalid service URL configured.");

    } catch (const HttpException& e) {
        if (e.isClientError()) {
            showError("Request failed: " + string(e.what()));
        } else if (e.isServerError()) {
            showError("Server error. Please try again later.");
        }
    }
}

