// Exception hierarchy for a document processing system
class DocumentException : public runtime_error {
public:
    using runtime_error::runtime_error;
};

class DocumentLoadException : public DocumentException {
    string documentPath_;
public:
    DocumentLoadException(const string& msg, const string& path)
        : DocumentException(msg + " [document: " + path + "]"),
          documentPath_(path) {}
    const string& documentPath() const { return documentPath_; }
};

class DocumentParseException : public DocumentException {
    string documentPath_;
    int line_;
    int column_;
public:
    DocumentParseException(const string& msg, const string& path, int line, int col)
        : DocumentException(msg + " at " + path + ":" + to_string(line) + ":" + to_string(col)),
          documentPath_(path), line_(line), column_(col) {}
    int line() const { return line_; }
    int column() const { return column_; }
};

class DocumentValidationException : public DocumentException {
    vector<string> validationErrors_;
public:
    explicit DocumentValidationException(vector<string> errors)
        : DocumentException("Document validation failed with " + 
                           to_string(errors.size()) + " errors"),
          validationErrors_(move(errors)) {}
    const vector<string>& errors() const { return validationErrors_; }
};

// Context-preserving exception translation
class DocumentProcessor {
    string currentDocument_;

public:
    ProcessedDocument process(const string& path) {
        currentDocument_ = path;

        try {
            auto raw = loadRawDocument(path);
            auto parsed = parseDocument(raw);
            validateDocument(parsed);
            return transformDocument(parsed);

        } catch (const FileException& e) {
            // Add context and re-throw
            throw DocumentLoadException(
                "Failed to load document: " + string(e.what()), path);

        } catch (const ParseException& e) {
            throw DocumentParseException(
                "Failed to parse document: " + string(e.what()),
                path, e.line(), e.column());

        } catch (const ValidationException& e) {
            throw DocumentValidationException(e.errors());

        } catch (const exception& e) {
            // Unknown error — wrap with context
            throw DocumentException(
                "Unexpected error processing " + path + ": " + e.what());
        }
    }

private:
    struct RawDocument { string content; };
    struct ParsedDocument {};
    struct ProcessedDocument {};

    RawDocument loadRawDocument(const string& path) {
        ifstream file(path);
        if (!file) throw FileException(path);
        return RawDocument{string(istreambuf_iterator<char>(file), {})};
    }

    ParsedDocument parseDocument(const RawDocument& raw) {
        // Simulated parsing
        return ParsedDocument{};
    }

    void validateDocument(const ParsedDocument&) {
        // Simulated validation
    }

    ProcessedDocument transformDocument(const ParsedDocument&) {
        return ProcessedDocument{};
    }

    // Exception types used internally
    struct FileException : runtime_error {
        using runtime_error::runtime_error;
    };
    struct ParseException : runtime_error {
        int line_, column_;
        ParseException(const string& msg, int l, int c) 
            : runtime_error(msg), line_(l), column_(c) {}
        int line() const { return line_; }
        int column() const { return column_; }
    };
    struct ValidationException : runtime_error {
        vector<string> errors_;
        explicit ValidationException(vector<string> e) 
            : runtime_error("validation failed"), errors_(move(e)) {}
        const vector<string>& errors() const { return errors_; }
    };
};

// noexcept usage
class Buffer {
    unique_ptr<char[]> data_;
    size_t size_;

public:
    Buffer(size_t size) : data_(make_unique<char[]>(size)), size_(size) {}

    // Move operations should never throw
    Buffer(Buffer&& other) noexcept 
        : data_(move(other.data_)), size_(other.size_) {
        other.size_ = 0;
    }

    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            data_ = move(other.data_);
            size_ = other.size_;
            other.size_ = 0;
        }
        return *this;
    }

    // Swap should never throw
    void swap(Buffer& other) noexcept {
        using std::swap;
        swap(data_, other.data_);
        swap(size_, other.size_);
    }

    // Destructor must never throw
    ~Buffer() noexcept = default;

    size_t size() const noexcept { return size_; }
    bool empty() const noexcept { return size_ == 0; }
};

// Function that guarantees no exceptions
extern "C" void cCompatibleFunction() noexcept {
    // Implementation must not throw
}

int main() {
