    try {
        auto result = processor.process("document.xml");
        cout << "Document processed successfully\n";
    } catch (const DocumentLoadException& e) {
        cerr << "Load error: " << e.what() << "\n";
    } catch (const DocumentParseException& e) {
        cerr << "Parse error at line " << e.line() 
             << ", col " << e.column() << "\n";
    } catch (const DocumentValidationException& e) {
        cerr << "Validation errors:\n";
        for (const auto& err : e.errors()) {
            cerr << "  - " << err << "\n";
        }
    } catch (const DocumentException& e) {
        cerr << "Document error: " << e.what() << "\n";
    }

    return 0;
}

