// CLEAN: Special Case Pattern — no null checks needed
class CustomerInterface {
public:
    virtual ~CustomerInterface() = default;
    virtual string getName() const = 0;
    virtual string getEmail() const = 0;
    virtual void sendNotification(const string& message) const = 0;
    virtual bool isValid() const = 0;
    virtual PaymentMethod getPaymentMethod() const = 0;
};

class RealCustomer : public CustomerInterface {
    string id_;
    string name_;
    string email_;
    PaymentMethod payment_;

public:
    RealCustomer(string id, string name, string email, PaymentMethod payment)
        : id_(move(id)), name_(move(name)), email_(move(email)), payment_(move(payment)) {}

    string getName() const override { return name_; }
    string getEmail() const override { return email_; }

    void sendNotification(const string& message) const override {
        cout << "[Email to " << email_ << "] " << message << "\n";
    }

    bool isValid() const override { return true; }
    PaymentMethod getPaymentMethod() const override { return payment_; }
};

class NullCustomer : public CustomerInterface {
public:
    string getName() const override { return "Guest"; }
    string getEmail() const override { return ""; }
    void sendNotification(const string&) const override {
        // No-op: silently do nothing
    }
    bool isValid() const override { return false; }
    PaymentMethod getPaymentMethod() const override {
        return PaymentMethod::NONE;  // Safe default
    }
};

// Repository always returns a valid object
class CustomerRepositorySpecialCase {
    map<string, RealCustomer> customers_;
    static NullCustomer nullCustomer_;

public:
    const CustomerInterface& findById(const string& id) {
        auto it = customers_.find(id);
        if (it == customers_.end()) {
            return nullCustomer_;
        }
        return it->second;
    }

    void addCustomer(const string& id, const RealCustomer& customer) {
        customers_.emplace(id, customer);
    }
};

