// Custom RAII wrapper for a C-style resource
class FileHandle {
    FILE* handle_;
    string path_;

public:
    explicit FileHandle(const string& path, const string& mode)
        : handle_(fopen(path.c_str(), mode.c_str())), path_(path) {
        if (!handle_) {
            throw FileException("Cannot open: " + path);
        }
    }

    // Disable copying — unique ownership
    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    // Enable moving
    FileHandle(FileHandle&& other) noexcept 
        : handle_(other.handle_), path_(move(other.path_)) {
        other.handle_ = nullptr;
    }

    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            close();
            handle_ = other.handle_;
            path_ = move(other.path_);
            other.handle_ = nullptr;
        }
        return *this;
    }

    // Destructor guarantees cleanup
    ~FileHandle() noexcept {
        close();
    }

    FILE* get() const { return handle_; }
    bool isOpen() const { return handle_ != nullptr; }

    size_t write(const string& data) {
        return fwrite(data.c_str(), 1, data.size(), handle_);
    }

    string readAll() {
        fseek(handle_, 0, SEEK_END);
        auto size = ftell(handle_);
        fseek(handle_, 0, SEEK_SET);

        string content(size, '\0');
        fread(content.data(), 1, size, handle_);
        return content;
    }

private:
    void close() noexcept {
        if (handle_) {
            fclose(handle_);
            handle_ = nullptr;
        }
    }

    struct FileException : runtime_error {
        using runtime_error::runtime_error;
    };
};

// RAII for scoped operations
class ScopedTimer {
    string name_;
    chrono::steady_clock::time_point start_;

public:
    explicit ScopedTimer(string name)
        : name_(move(name)), start_(chrono::steady_clock::now()) {}

    ~ScopedTimer() {
        auto elapsed = chrono::steady_clock::now() - start_;
        auto ms = chrono::duration_cast<chrono::milliseconds>(elapsed).count();
        cout << "[Timer] " << name_ << ": " << ms << "ms\n";
    }
};

// RAII for transaction-like rollback
class DatabaseTransaction {
    Database& db_;
    bool committed_ = false;
    vector<string> rollbackStatements_;

public:
    explicit DatabaseTransaction(Database& db) : db_(db) {
        db_.execute("BEGIN TRANSACTION");
    }

    void execute(const string& sql) {
        // Record rollback info before executing
        rollbackStatements_.push_back(generateRollback(sql));
        db_.execute(sql);
    }

    void commit() {
        db_.execute("COMMIT");
        committed_ = true;
    }

    // Automatic rollback if not committed
    ~DatabaseTransaction() {
        if (!committed_) {
            try {
                for (auto it = rollbackStatements_.rbegin(); 
                     it != rollbackStatements_.rend(); ++it) {
                    db_.execute(*it);
                }
                db_.execute("ROLLBACK");
            } catch (...) {
                // Log but don't throw from destructor
                cerr << "Rollback failed!\n";
            }
        }
    }

private:
    string generateRollback(const string& sql) {
        // Simplified — real implementation would parse SQL
        return "/* rollback for: " + sql + " */";
    }
};

// Strong exception safety with copy-and-swap
class ConfigManager {
    map<string, string> settings_;
    mutable shared_mutex mutex_;

public:
    // Strong guarantee: if anything fails, settings_ is unchanged
    void updateSettings(const map<string, string>& newSettings) {
        // Step 1: Work on a copy
        auto temp = settings_;  // Copy existing

        // Step 2: Modify the copy (might throw, but settings_ is safe)
        for (const auto& [key, value] : newSettings) {
            validateKey(key);
            validateValue(value);
            temp[key] = value;
        }

        // Step 3: Swap (noexcept) — atomic update
        lock_guard<shared_mutex> lock(mutex_);
        settings_.swap(temp);
    }  // temp destroyed here with old data

    // Basic guarantee: individual updates are atomic
    void setSetting(const string& key, const string& value) {
        validateKey(key);
        validateValue(value);

        lock_guard<shared_mutex> lock(mutex_);
        settings_[key] = value;
    }

    string getSetting(const string& key) const {
        shared_lock<shared_mutex> lock(mutex_);
        auto it = settings_.find(key);
        if (it == settings_.end()) {
            throw out_of_range("Setting not found: " + key);
        }
        return it->second;
    }

private:
    void validateKey(const string& key) {
        if (key.empty()) throw invalid_argument("Key cannot be empty");
        if (key.find(' ') != string::npos) throw invalid_argument("Key cannot contain spaces");
    }

    void validateValue(const string& value) {
        if (value.size() > 10000) throw invalid_argument("Value too large");
    }
};

