        ScopedTimer timer("Heavy computation");
        // ... do work ...
        this_thread::sleep_for(chrono::milliseconds(100));
    }  // Timer logs elapsed time here

    // Transaction automatically rolls back if not committed
    Database db;
    try {
        DatabaseTransaction tx(db);
        tx.execute("INSERT INTO users VALUES ('alice')");
        tx.execute("INSERT INTO logs VALUES ('user created')");

        throw runtime_error("Simulated failure!");
        tx.commit();  // Never reached

    } catch (const exception& e) {
        cout << "Transaction failed: " << e.what() << "\n";
        // Transaction destructor rolls back automatically!
    }
}

int main() {
    demonstrateRAII();
    return 0;
}

