// The wrapper hides all libpng details
class PngImageLoader {
public:
    struct LoadOptions {
        bool convertToRgba = false;
        bool stripAlpha = false;
        int maxDimension = 4096;
    };

    Image load(const string& path, const LoadOptions& options = {}) {
        // All libpng code isolated here
        auto png = createPngReadStruct();
        auto info = createPngInfoStruct(png.get());

        auto file = openFile(path);
        png_init_io(png.get(), file.get());
        png_read_info(png.get(), info.get());

        auto width = png_get_image_width(png.get(), info.get());
        auto height = png_get_image_height(png.get(), info.get());

        validateDimensions(width, height, options.maxDimension);

        auto format = determineFormat(info.get());
        auto image = Image(width, height, format);

        readPixels(png.get(), info.get(), image);

        if (options.convertToRgba && format != Image::Format::RGBA) {
            image = convertToRgba(image);
        }

        return image;
    }

    void save(const string& path, const Image& image, int compressionLevel = 6) {
        // All libpng save code isolated here
    }

private:
    struct PngDeleter {
        void operator()(png_structp png) {
            if (png) png_destroy_read_struct(&png, nullptr, nullptr);
        }
    };
    struct InfoDeleter {
        void operator()(png_infop info) {
            // Info is destroyed with png struct in our case
        }
    };

    unique_ptr<png_struct, PngDeleter> createPngReadStruct() {
        auto png = png_create_read_struct(PNG_LIBPNG_VER_STRING, nullptr, nullptr, nullptr);
        if (!png) throw ImageLoadException("Failed to create PNG read struct");
        return unique_ptr<png_struct, PngDeleter>(png);
    }

    unique_ptr<png_info, InfoDeleter> createPngInfoStruct(png_structp png) {
        auto info = png_create_info_struct(png);
        if (!info) throw ImageLoadException("Failed to create PNG info struct");
        return unique_ptr<png_info, InfoDeleter>(info);
    }

    unique_ptr<FILE, decltype(&fclose)> openFile(const string& path) {
        FILE* fp = fopen(path.c_str(), "rb");
        if (!fp) throw ImageLoadException("Cannot open: " + path);
        return unique_ptr<FILE, decltype(&fclose)>(fp, &fclose);
    }

    void validateDimensions(int width, int height, int maxDim) {
        if (width > maxDim || height > maxDim) {
            throw ImageLoadException("Image too large: " + 
                                     to_string(width) + "x" + to_string(height));
        }
    }

    Image::Format determineFormat(png_infop info) {
        auto colorType = png_get_color_type(nullptr, info);
        switch (colorType) {
            case PNG_COLOR_TYPE_RGB: return Image::Format::RGB;
            case PNG_COLOR_TYPE_RGBA: return Image::Format::RGBA;
            case PNG_COLOR_TYPE_GRAY: return Image::Format::GRAYSCALE;
            default: throw ImageLoadException("Unsupported color type");
        }
    }

    void readPixels(png_structp png, png_infop info, Image& image);
    Image convertToRgba(const Image& image);

    struct ImageLoadException : runtime_error {
        using runtime_error::runtime_error;
    };
};

// Business logic uses clean Image API, knows nothing about libpng
class ImageProcessor {
public:
    Image applyFilter(const Image& input, const string& filterName) {
        Image output(input.width(), input.height(), input.format());

        for (int y = 0; y < input.height(); ++y) {
            for (int x = 0; x < input.width(); ++x) {
                auto pixel = input.pixelAt(x, y);
                auto filtered = applyFilterToPixel(pixel, filterName);
                output.setPixel(x, y, filtered);
            }
        }

        return output;
    }

    Image thumbnail(const Image& input, int maxSize) {
        auto scale = min(maxSize / double(input.width()), 
                        maxSize / double(input.height()));
        auto newWidth = static_cast<int>(input.width() * scale);
        auto newHeight = static_cast<int>(input.height() * scale);

        // Resizing logic...
        return Image(newWidth, newHeight, input.format());
    }

private:
    Image::Pixel applyFilterToPixel(Image::Pixel p, const string& filter) {
        if (filter == "grayscale") {
            auto gray = static_cast<uint8_t>(0.299 * p.r + 0.587 * p.g + 0.114 * p.b);
            return {gray, gray, gray, p.a};
        }
        if (filter == "invert") {
            return {static_cast<uint8_t>(255 - p.r),
                    static_cast<uint8_t>(255 - p.g),
                    static_cast<uint8_t>(255 - p.b),
                    p.a};
        }
        return p;
    }
};

