// Example: Learning tests for a JSON library (nlohmann/json)
// These tests document our understanding and catch breaking changes

#include <nlohmann/json.hpp>
using json = nlohmann::json;

// Learning test: How does the library handle missing keys?
TEST(JsonLibraryLearning, MissingKeyBehavior) {
    json j = {{"name", "Alice"}, {"age", 30}};

    // Does at() throw?
    EXPECT_THROW(j.at("missing"), json::out_of_range);

    // Does operator[] create a null entry?
    auto& ref = j["also_missing"];
    EXPECT_TRUE(ref.is_null());
    EXPECT_TRUE(j.contains("also_missing"));  // It was created!

    // Does value() provide a default?
    EXPECT_EQ(j.value("missing", "default"), "default");
    EXPECT_EQ(j.value("name", "default"), "Alice");
}

// Learning test: Type conversion behavior
TEST(JsonLibraryLearning, TypeConversions) {
    json j = {{"int_str", "42"}, {"float_str", "3.14"}, 
              {"bool_str", "true"}, {"actual_int", 42}};

    // String "42" to int — does it convert or throw?
    EXPECT_THROW(j["int_str"].get<int>(), json::type_error);

    // But stoi works
    EXPECT_EQ(stoi(j["int_str"].get<string>()), 42);

    // Actual int works fine
    EXPECT_EQ(j["actual_int"].get<int>(), 42);

    // Implicit conversion from int to double?
    EXPECT_DOUBLE_EQ(j["actual_int"].get<double>(), 42.0);
}

// Learning test: Array behavior
TEST(JsonLibraryLearning, ArrayOperations) {
    json arr = json::array();
    EXPECT_TRUE(arr.empty());

    arr.push_back(1);
    arr.push_back(2);
    EXPECT_EQ(arr.size(), 2);

    // Does it support initializer list construction?
    json arr2 = {1, 2, 3, 4, 5};
    EXPECT_EQ(arr2.size(), 5);

    // Range-based for loop?
    int sum = 0;
    for (const auto& elem : arr2) {
        sum += elem.get<int>();
    }
    EXPECT_EQ(sum, 15);
}

// Learning test: Large number handling
TEST(JsonLibraryLearning, LargeNumbers) {
    // Does it preserve precision for large integers?
    json j = {{"big_int", 9007199254740991LL}};  // 2^53 - 1
    EXPECT_EQ(j["big_int"].get<int64_t>(), 9007199254740991LL);

    // What about beyond safe integer range for JS?
    json j2 = {{"too_big", 9007199254740993LL}};
    // nlohmann/json stores as number, but may lose precision if 
    // serialized to JS-compatible format
}

// Learning test: Exception safety
TEST(JsonLibraryLearning, ParseErrors) {
    // Invalid JSON
    string badJson = "{\"name\": \"Alice\", \"age\"}";  // Missing value
    EXPECT_THROW(json::parse(badJson), json::parse_error);

    // Empty string
    EXPECT_THROW(json::parse(""), json::parse_error);

    // Just whitespace
    EXPECT_THROW(json::parse("   "), json::parse_error);
}

