namespace ThirdPartyPayment {
    struct PaymentRequest {
        char merchant_id[32];
        char customer_token[64];
        double amount;
        char currency[4];  // "USD", "EUR"
        int request_type;  // 1 = charge, 2 = refund, 3 = auth
        void* callback_data;
    };

    struct PaymentResponse {
        int status;  // 0 = success, 1 = declined, 2 = error, 3 = pending
        char transaction_id[32];
        char error_message[256];
        double processed_amount;
    };

    // C-style API
    int initialize(const char* api_key, const char* environment);
    PaymentResponse process_payment(const PaymentRequest* req);
    int void_transaction(const char* transaction_id);
    void cleanup();
}

// === Our clean domain model ===

enum class PaymentStatus { SUCCESS, DECLINED, ERROR, PENDING };
enum class TransactionType { CHARGE, REFUND, AUTHORIZATION };

struct Money {
    double amount;
    string currency;
};

struct PaymentResult {
    PaymentStatus status;
    string transactionId;
    string errorMessage;
    Money processedAmount;
    bool wasSuccessful() const { return status == PaymentStatus::SUCCESS; }
};

struct CustomerPaymentInfo {
    string customerToken;
    Money amount;
    TransactionType type;
};

// === Adapter: Translates between our domain and the messy external API ===

class PaymentGatewayAdapter {
    string apiKey_;
    bool initialized_ = false;

public:
    explicit PaymentGatewayAdapter(const string& apiKey) : apiKey_(apiKey) {}

    ~PaymentGatewayAdapter() {
        if (initialized_) {
            ThirdPartyPayment::cleanup();
        }
    }

    void initialize(bool useProduction = false) {
        auto env = useProduction ? "production" : "sandbox";
        int result = ThirdPartyPayment::initialize(apiKey_.c_str(), env);
        if (result != 0) {
            throw PaymentGatewayException("Failed to initialize: code " + to_string(result));
        }
        initialized_ = true;
    }

    PaymentResult charge(const string& merchantId, const CustomerPaymentInfo& payment) {
        auto request = createRequest(merchantId, payment);
        auto response = ThirdPartyPayment::process_payment(&request);
        return translateResponse(response);
    }

    void voidTransaction(const string& transactionId) {
        int result = ThirdPartyPayment::void_transaction(transactionId.c_str());
        if (result != 0) {
            throw PaymentGatewayException("Failed to void transaction: " + transactionId);
        }
    }

private:
    ThirdPartyPayment::PaymentRequest createRequest(
        const string& merchantId, const CustomerPaymentInfo& payment) {

        ThirdPartyPayment::PaymentRequest req{};

        // Safe string copy with bounds checking
        strncpy(req.merchant_id, merchantId.c_str(), sizeof(req.merchant_id) - 1);
        strncpy(req.customer_token, payment.customerToken.c_str(), 
                sizeof(req.customer_token) - 1);

        req.amount = payment.amount.amount;
        strncpy(req.currency, payment.amount.currency.c_str(), 
                sizeof(req.currency) - 1);

        req.request_type = translateTransactionType(payment.type);
        req.callback_data = nullptr;

        return req;
    }

    int translateTransactionType(TransactionType type) {
        switch (type) {
            case TransactionType::CHARGE: return 1;
            case TransactionType::REFUND: return 2;
            case TransactionType::AUTHORIZATION: return 3;
            default: throw PaymentGatewayException("Unknown transaction type");
        }
    }

    PaymentResult translateResponse(const ThirdPartyPayment::PaymentResponse& response) {
        PaymentResult result;
        result.transactionId = response.transaction_id;
        result.errorMessage = response.error_message;
        result.processedAmount = {response.processed_amount, "USD"};

        switch (response.status) {
            case 0: result.status = PaymentStatus::SUCCESS; break;
            case 1: result.status = PaymentStatus::DECLINED; break;
            case 2: result.status = PaymentStatus::ERROR; break;
            case 3: result.status = PaymentStatus::PENDING; break;
            default: result.status = PaymentStatus::ERROR; break;
        }

        return result;
    }

    struct PaymentGatewayException : runtime_error {
        using runtime_error::runtime_error;
    };
};

// === Our domain code uses only the clean adapter interface ===

class OrderService {
    PaymentGatewayAdapter& paymentGateway_;

public:
    explicit OrderService(PaymentGatewayAdapter& gateway) : paymentGateway_(gateway) {}

    OrderResult processOrder(const Order& order) {
        auto paymentInfo = CustomerPaymentInfo{
            order.customerPaymentToken(),
            order.total(),
            TransactionType::CHARGE
        };

        auto result = paymentGateway_.charge("MERCHANT_001", paymentInfo);

        if (result.wasSuccessful()) {
            return OrderResult::success(result.transactionId);
        }

        if (result.status == PaymentStatus::DECLINED) {
            return OrderResult::declined(result.errorMessage);
        }

        if (result.status == PaymentStatus::PENDING) {
            return OrderResult::pending(result.transactionId);
        }

        return OrderResult::error(result.errorMessage);
    }

    void cancelOrder(const string& transactionId) {
        paymentGateway_.voidTransaction(transactionId);
    }
};

