// === Logging at boundaries ===

template<typename Func>
auto logBoundaryCall(const string& operation, Func&& func) {
    auto start = chrono::steady_clock::now();
    try {
        auto result = func();
        auto elapsed = chrono::duration_cast<chrono::milliseconds>(
            chrono::steady_clock::now() - start).count();
        cout << "[BOUNDARY] " << operation << " succeeded in " << elapsed << "ms\n";
        return result;
    } catch (const exception& e) {
        auto elapsed = chrono::duration_cast<chrono::milliseconds>(
            chrono::steady_clock::now() - start).count();
        cerr << "[BOUNDARY] " << operation << " FAILED after " << elapsed 
             << "ms: " << e.what() << "\n";
        throw;
    }
}

