// REFACTOR: Extract delimiter logic
class StringCalculatorFinal {
public:
    int add(const string& numbers) {
        if (numbers.empty()) return 0;

        auto delimiters = getDelimiters(numbers);
        auto numberString = getNumberString(numbers);

        auto values = split(numberString, delimiters);
        return sumValues(values);
    }

private:
    vector<char> getDelimiters(const string& numbers) {
        if (numbers.starts_with("//")) {
            return {numbers[2]};
        }
        return {',', '\n'};
    }

    string getNumberString(const string& numbers) {
        if (numbers.starts_with("//")) {
            auto newlinePos = numbers.find('\n');
            return numbers.substr(newlinePos + 1);
        }
        return numbers;
    }

    vector<string> split(const string& str, const vector<char>& delimiters) {
        vector<string> tokens;
        string current;

        for (char c : str) {
            if (find(delimiters.begin(), delimiters.end(), c) != delimiters.end()) {
                if (!current.empty()) {
                    tokens.push_back(current);
                    current.clear();
                }
            } else {
                current += c;
            }
        }
        if (!current.empty()) tokens.push_back(current);

        return tokens;
    }

    int sumValues(const vector<string>& values) {
        int sum = 0;
        for (const auto& val : values) {
            auto num = stoi(val);
            if (num < 0) throw invalid_argument("Negatives not allowed: " + val);
            if (num > 1000) continue;  // Ignore large numbers
            sum += num;
        }
        return sum;
    }
};

// === Demonstrating the final implementation ===
int main() {
    StringCalculatorFinal calc;

    // All these would be separate test cases in TDD
    assert(calc.add("") == 0);
    assert(calc.add("5") == 5);
    assert(calc.add("1,2") == 3);
    assert(calc.add("1,2,3,4,5") == 15);
    assert(calc.add("1\n2,3") == 6);
    assert(calc.add("//;\n1;2;3") == 6);
    assert(calc.add("2,1001") == 2);  // Ignores > 1000

    try {
        calc.add("-1,2");
        assert(false);  // Should have thrown
    } catch (const invalid_argument&) {
        // Expected
    }

    cout << "All String Calculator tests passed!\n";
    return 0;
}

