// Repeatable: Control time with dependency injection
class Clock {
public:
    virtual ~Clock() = default;
    virtual chrono::system_clock::time_point now() const {
        return chrono::system_clock::now();
    }
};

class FixedClock : public Clock {
    chrono::system_clock::time_point fixedTime_;

public:
    explicit FixedClock(chrono::system_clock::time_point t) : fixedTime_(t) {}
    chrono::system_clock::time_point now() const override { return fixedTime_; }
};

class BusinessHoursChecker {
    const Clock& clock_;

public:
    explicit BusinessHoursChecker(const Clock& clock) : clock_(clock) {}

    bool isBusinessHours() const {
        auto now = clock_.now();
        auto time = chrono::system_clock::to_time_t(now);
        auto* local = localtime(&time);
        auto hour = local->tm_hour;
        return hour >= 9 && hour < 17;
    }
};

// Self-validating: Clear assertions, no manual inspection
void testBusinessHours() {
    // Test Monday 10 AM — should be business hours
    auto monday10am = chrono::system_clock::from_time_t(1700000000);
    FixedClock clock(monday10am);
    BusinessHoursChecker checker(clock);
    assert(checker.isBusinessHours() == true);

    // Test Sunday 10 AM — should not be business hours
    auto sunday10am = chrono::system_clock::from_time_t(1700000000 + 86400);
    FixedClock clock2(sunday10am);
    BusinessHoursChecker checker2(clock2);
    assert(checker2.isBusinessHours() == false);
}

