    }

    void missingUppercase() {
        PasswordValidator validator;
        auto result = validator.validate("abcdef1!");
        assert(!result.isValid);
        assert(contains(result.errors, "Must contain uppercase letter"));
    }

    void validPassword() {
        PasswordValidator validator;
        auto result = validator.validate("Abcdef1!");
        assert(result.isValid);
        assert(result.errors.empty());
    }

private:
    bool contains(const vector<string>& vec, const string& str) {
        return find(vec.begin(), vec.end(), str) != vec.end();
    }
};

