class ShoppingCart {
    vector<pair<string, double>> items_;
    double discount_ = 0.0;

public:
    void addItem(const string& name, double price) {
        items_.push_back({name, price});
    }

    void applyDiscount(double percentage) {
        if (percentage < 0 || percentage > 1.0) {
            throw invalid_argument("Discount must be between 0 and 1");
        }
        discount_ = percentage;
    }

    double total() const {
        double subtotal = 0.0;
        for (const auto& [name, price] : items_) {
            subtotal += price;
        }
        return subtotal * (1.0 - discount_);
    }

    int itemCount() const { return items_.size(); }
    bool isEmpty() const { return items_.empty(); }
};

// === Well-structured tests ===

class ShoppingCartTest {
public:
    void emptyCartHasZeroTotal() {
        // Arrange
        ShoppingCart cart;

        // Act
        auto total = cart.total();

        // Assert
        assert(total == 0.0);
        assert(cart.isEmpty());
    }

    void addingItemIncreasesTotal() {
        // Arrange
        ShoppingCart cart;

        // Act
        cart.addItem("Apple", 1.50);
        cart.addItem("Banana", 0.75);

        // Assert
        assert(cart.total() == 2.25);
        assert(cart.itemCount() == 2);
    }

    void discountReducesTotal() {
        // Arrange
        ShoppingCart cart;
        cart.addItem("Laptop", 1000.0);
        cart.addItem("Mouse", 50.0);

        // Act
        cart.applyDiscount(0.10);  // 10% off

        // Assert
        assert(cart.total() == 945.0);  // 1050 * 0.9
    }

    void invalidDiscountThrows() {
        // Arrange
        ShoppingCart cart;

        // Act & Assert
        try {
            cart.applyDiscount(1.5);  // Invalid: > 100%
            assert(false);  // Should not reach here
        } catch (const invalid_argument& e) {
            assert(string(e.what()).find("Discount") != string::npos);
        }
    }

