        // Arrange
        ShoppingCart cart;
        cart.addItem("Book", 100.0);
        cart.applyDiscount(0.20);

        // Act
        cart.applyDiscount(0.10);  // New discount overwrites old

        // Assert
        assert(cart.total() == 90.0);  // Not 80.0
    }
};

