class OrderProcessingTest {
public:
    void givenOrderWithItems_whenProcessing_thenCalculatesCorrectTotal() {
        // Given (Arrange)
        Order order;
        order.addLineItem("Widget", 2, 25.0);
        order.addLineItem("Gadget", 1, 75.0);

        // When (Act)
        order.process();

        // Then (Assert)
        assert(order.total() == 125.0);
        assert(order.status() == OrderStatus::PROCESSED);
    }

    void givenEmptyOrder_whenProcessing_thenThrowsInvalidOrder() {
        // Given
        Order order;

        // When & Then
        try {
            order.process();
            assert(false);
        } catch (const InvalidOrderException&) {
            // Expected
        }
    }

private:
    struct Order {
        struct LineItem { string name; int qty; double price; };
        vector<LineItem> items_;
        OrderStatus status_ = OrderStatus::PENDING;
        double total_ = 0.0;

        void addLineItem(const string& name, int qty, double price) {
            items_.push_back({name, qty, price});
        }

        void process() {
            if (items_.empty()) throw InvalidOrderException();
            for (const auto& item : items_) {
                total_ += item.qty * item.price;
            }
            status_ = OrderStatus::PROCESSED;
        }

        double total() const { return total_; }
        OrderStatus status() const { return status_; }
    };

    enum class OrderStatus { PENDING, PROCESSED };
    struct InvalidOrderException : exception {};
};

