// === Interfaces for dependencies ===

class PaymentGateway {
public:
    virtual ~PaymentGateway() = default;
    virtual string charge(const string& cardToken, double amount, const string& currency) = 0;
    virtual void refund(const string& transactionId) = 0;
};

class EmailService {
public:
    virtual ~EmailService() = default;
    virtual void send(const string& to, const string& subject, const string& body) = 0;
};

class InventoryService {
public:
    virtual ~InventoryService() = default;
    virtual bool reserve(const string& sku, int quantity) = 0;
    virtual void release(const string& sku, int quantity) = 0;
};

// === System Under Test ===

class OrderService {
    PaymentGateway& payment_;
    EmailService& email_;
    InventoryService& inventory_;

public:
    OrderService(PaymentGateway& p, EmailService& e, InventoryService& i)
        : payment_(p), email_(e), inventory_(i) {}

    OrderResult placeOrder(const Order& order) {
        // Reserve inventory first
        for (const auto& item : order.items) {
            if (!inventory_.reserve(item.sku, item.quantity)) {
                // Rollback previously reserved items
                rollbackInventory(order.items);
                return OrderResult::failed("INVENTORY_UNAVAILABLE");
            }
        }

        try {
            auto txnId = payment_.charge(order.cardToken, order.total, order.currency);

            email_.send(order.customerEmail,
                       "Order Confirmed",
                       "Your order has been placed. Transaction: " + txnId);

            return OrderResult::success(txnId);

        } catch (const PaymentException& e) {
            rollbackInventory(order.items);
            return OrderResult::failed("PAYMENT_FAILED: " + string(e.what()));
        }
    }

private:
    void rollbackInventory(const vector<OrderItem>& items) {
        for (const auto& item : items) {
            inventory_.release(item.sku, item.quantity);
        }
    }
};

