    bool wasEmailSentTo(const string& to) const {
        return any_of(sentEmails.begin(), sentEmails.end(),
                      [&](const auto& e) { return e.to == to; });
    }

    size_t emailCount() const { return sentEmails.size(); }
};

// === FAKE: Working in-memory implementation ===

class FakeInventoryService : public InventoryService {
    map<string, int> stock_;
    map<string, int> reserved_;

public:
    void setStock(const string& sku, int quantity) {
        stock_[sku] = quantity;
        reserved_[sku] = 0;
    }

    bool reserve(const string& sku, int quantity) override {
        auto available = stock_[sku] - reserved_[sku];
        if (available < quantity) return false;
        reserved_[sku] += quantity;
        return true;
    }

    void release(const string& sku, int quantity) override {
        reserved_[sku] -= quantity;
    }

    int availableStock(const string& sku) const {
        auto it = stock_.find(sku);
        if (it == stock_.end()) return 0;
        auto rit = reserved_.find(sku);
        auto reserved = (rit == reserved_.end()) ? 0 : rit->second;
        return it->second - reserved;
    }
};

// === MOCK: Pre-programmed expectations ===

class MockPaymentGateway : public PaymentGateway {
public:
    struct Expectation {
        string expectedCardToken;
        double expectedAmount;
        string returnTransactionId;
    };

    void expectCharge(const string& cardToken, double amount, const string& returnId) {
        expectations_.push_back({cardToken, amount, returnId});
    }

    string charge(const string& cardToken, double amount, const string&) override {
        if (currentExpectation_ >= expectations_.size()) {
            throw runtime_error("Unexpected charge call");
        }
        auto& exp = expectations_[currentExpectation_++];
        assert(exp.expectedCardToken == cardToken);
        assert(exp.expectedAmount == amount);
        return exp.returnTransactionId;
    }

    void refund(const string&) override {}

    bool allExpectationsMet() const {
        return currentExpectation_ == expectations_.size();
    }

private:
    vector<Expectation> expectations_;
    size_t currentExpectation_ = 0;
};

