// === Comprehensive Parameterized Test Examples ===

class PasswordValidator {
public:
    struct Result {
        bool isValid;
        vector<string> errors;
    };

    Result validate(const string& password) {
        vector<string> errors;

        if (password.length() < 8) {
            errors.push_back("TOO_SHORT");
        }
        if (!hasUppercase(password)) {
            errors.push_back("NO_UPPERCASE");
        }
        if (!hasLowercase(password)) {
            errors.push_back("NO_LOWERCASE");
        }
        if (!hasDigit(password)) {
            errors.push_back("NO_DIGIT");
        }
        if (!hasSpecialChar(password)) {
            errors.push_back("NO_SPECIAL");
        }

        return Result{errors.empty(), errors};
    }

private:
    bool hasUppercase(const string& s) {
        return any_of(s.begin(), s.end(), ::isupper);
    }
    bool hasLowercase(const string& s) {
        return any_of(s.begin(), s.end(), ::islower);
    }
    bool hasDigit(const string& s) {
        return any_of(s.begin(), s.end(), ::isdigit);
    }
    bool hasSpecialChar(const string& s) {
        return any_of(s.begin(), s.end(), [](char c) {
            return string("!@#$%^&*()_+-=[]{}|;:,.<>?").find(c) != string::npos;
        });
    }
};

// Manual parameterized test (works with any framework)
struct PasswordTestCase {
    string password;
    bool expectedValid;
    vector<string> expectedErrors;
    string description;
};

void runPasswordTests() {
    vector<PasswordTestCase> cases = {
        // Valid passwords
        {"Password1!", true, {}, "Valid: all requirements met"},
        {"MyP@ssw0rd", true, {}, "Valid: another valid password"},
        {"A1b2C3d!", true, {}, "Valid: mixed with special"},

        // Invalid: too short
        {"Short1!", false, {"TOO_SHORT"}, "Invalid: 7 chars"},
        {"A1!", false, {"TOO_SHORT"}, "Invalid: 3 chars"},
        {"", false, {"TOO_SHORT", "NO_UPPERCASE", "NO_LOWERCASE", "NO_DIGIT", "NO_SPECIAL"}, 
         "Invalid: empty"},

        // Invalid: missing character types
        {"password1!", false, {"NO_UPPERCASE"}, "Invalid: no uppercase"},
        {"PASSWORD1!", false, {"NO_LOWERCASE"}, "Invalid: no lowercase"},
        {"Password!!", false, {"NO_DIGIT"}, "Invalid: no digit"},
        {"Password12", false, {"NO_SPECIAL"}, "Invalid: no special"},

        // Invalid: multiple failures
        {"short", false, {"TOO_SHORT", "NO_UPPERCASE", "NO_DIGIT", "NO_SPECIAL"}, 
         "Invalid: multiple failures"},
        {"12345678", false, {"NO_UPPERCASE", "NO_LOWERCASE", "NO_SPECIAL"}, 
         "Invalid: only digits"},
    };

    PasswordValidator validator;
    int passed = 0, failed = 0;

    for (const auto& tc : cases) {
        auto result = validator.validate(tc.password);

        bool testPassed = (result.isValid == tc.expectedValid);
        if (!tc.expectedValid) {
            // Check that all expected errors are present
            for (const auto& err : tc.expectedErrors) {
                if (find(result.errors.begin(), result.errors.end(), err) == result.errors.end()) {
                    testPassed = false;
                    break;
                }
            }
            // And no extra errors
            if (result.errors.size() != tc.expectedErrors.size()) {
                testPassed = false;
            }
        }

        if (testPassed) {
            passed++;
            cout << "[PASS] " << tc.description << "\n";
        } else {
            failed++;
            cout << "[FAIL] " << tc.description << "\n";
            cout << "  Password: '" << tc.password << "'\n";
            cout << "  Expected valid: " << tc.expectedValid << ", got: " << result.isValid << "\n";
            cout << "  Expected errors: ";
            for (const auto& e : tc.expectedErrors) cout << e << " ";
            cout << "\n  Actual errors: ";
            for (const auto& e : result.errors) cout << e << " ";
            cout << "\n";
        }
    }

    cout << "\nResults: " << passed << " passed, " << failed << " failed\n";
    assert(failed == 0);
}

// === Range-based parameterized tests ===

class DateCalculator {
public:
    bool isLeapYear(int year) {
        if (year % 400 == 0) return true;
        if (year % 100 == 0) return false;
        return year % 4 == 0;
    }

    int daysInMonth(int year, int month) {
        static const int days[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (month == 2 && isLeapYear(year)) return 29;
        return days[month];
    }
};

void runDateTests() {
    DateCalculator calc;

    // Leap year tests
    struct LeapYearCase { int year; bool isLeap; string reason; };
    vector<LeapYearCase> leapCases = {
        {2000, true, "Divisible by 400"},
        {2400, true, "Divisible by 400"},
        {2004, true, "Divisible by 4, not 100"},
        {1900, false, "Divisible by 100, not 400"},
        {2100, false, "Divisible by 100, not 400"},
        {2001, false, "Not divisible by 4"},
        {0, true, "Year 0 (edge case)"},
        {-4, true, "Negative leap year (BC)"},
    };

    for (const auto& tc : leapCases) {
        auto result = calc.isLeapYear(tc.year);
        assert(result == tc.isLeap);
        cout << "[PASS] Year " << tc.year << " leap = " << tc.isLeap 
             << " (" << tc.reason << ")\n";
    }

    // Days in month tests
    struct DaysCase { int year; int month; int expected; string reason; };
    vector<DaysCase> daysCases = {
        {2023, 1, 31, "January"},
        {2023, 2, 28, "February (non-leap)"},
        {2024, 2, 29, "February (leap year)"},
        {1900, 2, 28, "February (century non-leap)"},
        {2000, 2, 29, "February (century leap)"},
        {2023, 4, 30, "April"},
        {2023, 12, 31, "December"},
    };

    for (const auto& tc : daysCases) {
        auto result = calc.daysInMonth(tc.year, tc.month);
        assert(result == tc.expected);
        cout << "[PASS] " << tc.year << "-" << tc.month << " has " << tc.expected 
             << " days (" << tc.reason << ")\n";
    }
}

// === Property-based testing concept ===
// Instead of specific examples, test properties that should always hold

class SortingTest {
public:
    void testSortProperties() {
        for (int trial = 0; trial < 100; ++trial) {
            auto input = generateRandomVector();
            auto sorted = input;
            sort(sorted.begin(), sorted.end());

            // Property 1: Result is sorted
            assert(is_sorted(sorted.begin(), sorted.end()));

            // Property 2: Same length as input
            assert(sorted.size() == input.size());

            // Property 3: Contains same elements (multiset equality)
            auto inputCopy = input;
            sort(inputCopy.begin(), inputCopy.end());
            assert(sorted == inputCopy);

            // Property 4: Idempotent — sorting again doesn't change
            auto sortedAgain = sorted;
            sort(sortedAgain.begin(), sortedAgain.end());
            assert(sorted == sortedAgain);
        }
        cout << "[PASS] 100 random sort property tests\n";
    }

private:
    vector<int> generateRandomVector() {
        vector<int> result;
        int size = rand() % 100;
        for (int i = 0; i < size; ++i) {
            result.push_back(rand() % 1000 - 500);  // -500 to 499
        }
        return result;
    }
};

