// === Advanced Fixture: Shared Resource Management ===

class DatabaseConnectionPool {
    queue<unique_ptr<DatabaseConnection>> available_;
    vector<unique_ptr<DatabaseConnection>> all_;

public:
    explicit DatabaseConnectionPool(int size) {
        for (int i = 0; i < size; ++i) {
            auto conn = make_unique<DatabaseConnection>(i);
            all_.push_back(conn.get());
            available_.push(move(conn));
        }
    }

    unique_ptr<DatabaseConnection, function<void(DatabaseConnection*)>> acquire() {
        if (available_.empty()) {
            throw runtime_error("No connections available");
        }
        auto* raw = available_.front().release();
        available_.pop();

        return unique_ptr<DatabaseConnection, function<void(DatabaseConnection*)>>(
            raw, [this](DatabaseConnection* conn) { release(conn); }
        );
    }

    int availableCount() const { return available_.size(); }

private:
    void release(DatabaseConnection* conn) {
        available_.push(unique_ptr<DatabaseConnection>(conn));
    }
};

class ConnectionPoolTest : public ::testing::Test {
protected:
    static void SetUpTestSuite() {
        // Runs once before all tests in the suite
        cout << "[Suite Setup] Creating shared test database\n";
        sharedDb_ = make_unique<DatabaseConnectionPool>(5);
    }

    static void TearDownTestSuite() {
        // Runs once after all tests in the suite
        cout << "[Suite Teardown] Cleaning up shared test database\n";
        sharedDb_.reset();
    }

    void SetUp() override {
        // Each test gets a fresh pool state
        initialAvailable_ = sharedDb_->availableCount();
    }

    static unique_ptr<DatabaseConnectionPool> sharedDb_;
    int initialAvailable_;
};

unique_ptr<DatabaseConnectionPool> ConnectionPoolTest::sharedDb_;

TEST_F(ConnectionPoolTest, CanAcquireConnection) {
    auto conn = sharedDb_->acquire();
    ASSERT_NE(conn, nullptr);
    ASSERT_EQ(sharedDb_->availableCount(), initialAvailable_ - 1);

    // Connection automatically released when conn goes out of scope
}

TEST_F(ConnectionPoolTest, ConnectionAutoReleases) {
    {
        auto conn = sharedDb_->acquire();
        ASSERT_EQ(sharedDb_->availableCount(), initialAvailable_ - 1);
    }  // conn destroyed here

    ASSERT_EQ(sharedDb_->availableCount(), initialAvailable_);
}

TEST_F(ConnectionPoolTest, ExhaustingPoolThrows) {
    vector<decltype(sharedDb_->acquire())> connections;

    // Acquire all connections
    for (int i = 0; i < initialAvailable_; ++i) {
        connections.push_back(sharedDb_->acquire());
    }

    ASSERT_EQ(sharedDb_->availableCount(), 0);
    ASSERT_THROW(sharedDb_->acquire(), runtime_error);

    // Release one and try again
    connections.pop_back();
    ASSERT_NO_THROW(sharedDb_->acquire());
}

