// Extracted from a larger class — now independently testable
class Tokenizer {
public:
    struct Token {
        enum Type { WORD, NUMBER, SYMBOL, END };
        Type type;
        string value;
    };

    vector<Token> tokenize(const string& input) {
        vector<Token> tokens;
        size_t i = 0;

        while (i < input.size()) {
            if (isspace(input[i])) {
                ++i;
                continue;
            }

            if (isalpha(input[i])) {
                tokens.push_back(readWord(input, i));
            } else if (isdigit(input[i])) {
                tokens.push_back(readNumber(input, i));
            } else {
                tokens.push_back({Token::SYMBOL, string(1, input[i])});
                ++i;
            }
        }

        tokens.push_back({Token::END, ""});
        return tokens;
    }

private:
    Token readWord(const string& input, size_t& i) {
        string word;
        while (i < input.size() && isalpha(input[i])) {
            word += input[i++];
        }
        return {Token::WORD, word};
    }

    Token readNumber(const string& input, size_t& i) {
        string num;
        while (i < input.size() && isdigit(input[i])) {
            num += input[i++];
        }
        return {Token::NUMBER, num};
    }
};

// Now we can test tokenization independently
void testTokenizer() {
    Tokenizer tokenizer;

    auto tokens = tokenizer.tokenize("hello 123 world");
    assert(tokens.size() == 4);  // 3 tokens + END
    assert(tokens[0].type == Tokenizer::Token::WORD);
    assert(tokens[0].value == "hello");
    assert(tokens[1].type == Tokenizer::Token::NUMBER);
    assert(tokens[1].value == "123");
    assert(tokens[2].type == Tokenizer::Token::WORD);
    assert(tokens[2].value == "world");

    cout << "[PASS] Tokenizer extracts and tests independently\n";
}

// === Approach 2: Test through public interface ===

class ExpressionEvaluator {
public:
    double evaluate(const string& expression) {
        auto tokens = tokenizer_.tokenize(expression);
        auto ast = parse(tokens);
        return evaluateAst(ast);
    }

private:
    Tokenizer tokenizer_;

    struct AstNode {
        enum Type { NUMBER, ADD, SUBTRACT, MULTIPLY, DIVIDE };
        Type type;
        double value = 0;
        unique_ptr<AstNode> left;
        unique_ptr<AstNode> right;
    };

    unique_ptr<AstNode> parse(const vector<Tokenizer::Token>& tokens) {
        // Complex parsing logic — private but tested through evaluate()
        if (tokens.empty() || tokens[0].type == Tokenizer::Token::END) {
            return nullptr;
        }

        auto node = make_unique<AstNode>();

        if (tokens[0].type == Tokenizer::Token::NUMBER) {
            node->type = AstNode::NUMBER;
            node->value = stod(tokens[0].value);
            return node;
        }

        // Simplified: just handle "number op number"
        if (tokens.size() >= 3 && tokens[1].type == Tokenizer::Token::SYMBOL) {
            node->left = make_unique<AstNode>();
            node->left->type = AstNode::NUMBER;
            node->left->value = stod(tokens[0].value);

            node->right = make_unique<AstNode>();
            node->right->type = AstNode::NUMBER;
            node->right->value = stod(tokens[2].value);

            if (tokens[1].value == "+") node->type = AstNode::ADD;
            else if (tokens[1].value == "-") node->type = AstNode::SUBTRACT;
            else if (tokens[1].value == "*") node->type = AstNode::MULTIPLY;
            else if (tokens[1].value == "/") node->type = AstNode::DIVIDE;
        }

        return node;
    }

    double evaluateAst(const unique_ptr<AstNode>& node) {
        if (!node) return 0;

        switch (node->type) {
            case AstNode::NUMBER: return node->value;
            case AstNode::ADD: return evaluateAst(node->left) + evaluateAst(node->right);
            case AstNode::SUBTRACT: return evaluateAst(node->left) - evaluateAst(node->right);
            case AstNode::MULTIPLY: return evaluateAst(node->left) * evaluateAst(node->right);
            case AstNode::DIVIDE: return evaluateAst(node->left) / evaluateAst(node->right);
        }
        return 0;
    }
};

// Test through public interface — covers private parse() and evaluateAst()
void testEvaluatorThroughPublicInterface() {
    ExpressionEvaluator eval;

    assert(eval.evaluate("42") == 42.0);
    assert(eval.evaluate("2 + 3") == 5.0);
    assert(eval.evaluate("10 - 4") == 6.0);
    assert(eval.evaluate("6 * 7") == 42.0);
    assert(eval.evaluate("8 / 2") == 4.0);

    cout << "[PASS] Evaluator tested through public interface\n";
}

// === Approach 3: Friend tests (use sparingly) ===

class SecureBuffer {
public:
    explicit SecureBuffer(size_t size) : data_(size, 0) {}

    void write(const vector<uint8_t>& data, size_t offset) {
        if (offset + data.size() > data_.size()) {
            throw out_of_range("Write exceeds buffer size");
        }
        copy(data.begin(), data.end(), data_.begin() + offset);
        scrubInput(data);
    }

    vector<uint8_t> read(size_t offset, size_t length) const {
        if (offset + length > data_.size()) {
            throw out_of_range("Read exceeds buffer size");
        }
        return vector<uint8_t>(data_.begin() + offset, 
                               data_.begin() + offset + length);
    }

    void clear() {
        fill(data_.begin(), data_.end(), 0);
    }

private:
    vector<uint8_t> data_;

    void scrubInput(const vector<uint8_t>& data) {
        // Security-critical: clear input after copying
        const_cast<vector<uint8_t>&>(data).assign(data.size(), 0);
    }

    bool isZeroed() const {
        return all_of(data_.begin(), data_.end(), [](uint8_t b) { return b == 0; });
    }

    // Grant test access to private methods
    friend class SecureBufferTest;
};

class SecureBufferTest {
public:
    void publicInterfaceWorks() {
        SecureBuffer buf(10);
        vector<uint8_t> data = {1, 2, 3, 4, 5};

        buf.write(data, 0);
        auto result = buf.read(0, 5);

        assert(result == vector<uint8_t>({1, 2, 3, 4, 5}));
        cout << "[PASS] Public interface works\n";
    }

    void scrubInputClearsSource() {
        SecureBuffer buf(10);
        vector<uint8_t> data = {1, 2, 3, 4, 5};

        buf.write(data, 0);

        // Friend access to verify private behavior
        assert(all_of(data.begin(), data.end(), [](uint8_t b) { return b == 0; }));
        cout << "[PASS] Input scrubbed after write (friend test)\n";
    }

    void isZeroedDetectsClearedBuffer() {
        SecureBuffer buf(10);

        // Friend access to private isZeroed()
        assert(buf.isZeroed());

        vector<uint8_t> data = {1, 2, 3};
        buf.write(data, 0);
        assert(!buf.isZeroed());

        buf.clear();
        assert(buf.isZeroed());

        cout << "[PASS] isZeroed works correctly (friend test)\n";
    }
};

// === Approach 4: pImpl with test access ===

class EncryptionEngine {
public:
    EncryptionEngine();
    ~EncryptionEngine();

    string encrypt(const string& plaintext, const string& key);
    string decrypt(const string& ciphertext, const string& key);

    // Test-only interface
    struct TestAccess {
        static string getInternalState(const EncryptionEngine& engine);
        static void setRounds(EncryptionEngine& engine, int rounds);
    };

private:
    class Impl;
    unique_ptr<Impl> pImpl_;
};

class EncryptionEngine::Impl {
public:
    int rounds_ = 10;
    string lastKey_;

    string encryptInternal(const string& plaintext, const string& key) {
        lastKey_ = key;
        // Simplified XOR for demonstration
        string result = plaintext;
        for (auto& c : result) c ^= key[0];
        return result;
    }
};

EncryptionEngine::EncryptionEngine() : pImpl_(make_unique<Impl>()) {}
EncryptionEngine::~EncryptionEngine() = default;

string EncryptionEngine::encrypt(const string& plaintext, const string& key) {
    return pImpl_->encryptInternal(plaintext, key);
}

string EncryptionEngine::decrypt(const string& ciphertext, const string& key) {
    // XOR is symmetric
    return pImpl_->encryptInternal(ciphertext, key);
}

string EncryptionEngine::TestAccess::getInternalState(const EncryptionEngine& engine) {
    return "rounds=" + to_string(engine.pImpl_->rounds_) + 
           ", lastKey=" + engine.pImpl_->lastKey_;
}

void EncryptionEngine::TestAccess::setRounds(EncryptionEngine& engine, int rounds) {
    engine.pImpl_->rounds_ = rounds;
}

void testPImplAccess() {
    EncryptionEngine engine;

    auto encrypted = engine.encrypt("hello", "key");
    auto decrypted = engine.decrypt(encrypted, "key");
    assert(decrypted == "hello");

    // Test-only access to internals
    auto state = EncryptionEngine::TestAccess::getInternalState(engine);
    assert(state.find("lastKey=key") != string::npos);

    EncryptionEngine::TestAccess::setRounds(engine, 5);

    cout << "[PASS] pImpl with test access works\n";
}

