class OrderValidator {
public:
    struct ValidationResult {
        bool isValid;
        string errorMessage;
    };

    ValidationResult validate(const Order& order) const {
        if (order.total() <= 0) {
            return {false, "Order total must be positive"};
        }
        if (order.items.empty()) {
            return {false, "Order must contain at least one item"};
        }
        return {true, ""};
    }
};

// Extracted: Pricing logic with Strategy pattern
class PricingStrategy {
public:
    virtual ~PricingStrategy() = default;
    virtual double applyDiscount(double total) const = 0;
};

class VipPricing : public PricingStrategy {
public:
    double applyDiscount(double total) const override {
        if (total > 1000) return total * 0.85;
        return total * 0.90;
    }
};

class LoyalPricing : public PricingStrategy {
public:
    double applyDiscount(double total) const override {
        if (total > 500) return total * 0.95;
        return total;
    }
};

class StandardPricing : public PricingStrategy {
public:
    double applyDiscount(double total) const override { return total; }
};

class PricingEngine {
    map<string, unique_ptr<PricingStrategy>> strategies_;

public:
    PricingEngine() {
        strategies_["VIP"] = make_unique<VipPricing>();
        strategies_["LOYAL"] = make_unique<LoyalPricing>();
    }

    double calculateTotal(const Order& order) const {
        double subtotal = 0;
        for (const auto& item : order.items) {
            subtotal += item.total();
        }

        double tax = subtotal * 0.08;
        double beforeDiscount = subtotal + tax;

        auto it = strategies_.find(order.customerType);
        if (it != strategies_.end()) {
            return it->second->applyDiscount(beforeDiscount);
        }
        return beforeDiscount;
    }
};

