// Clean, focused OrderProcessor
class OrderProcessor {
    OrderValidator validator_;
    PricingEngine pricing_;
    ReceiptPrinter printer_;
    OrderRepository& repository_;

public:
    explicit OrderProcessor(OrderRepository& repo) : repository_(repo) {}

    void process(const vector<Order>& orders) {
        for (const auto& order : orders) {
            auto validation = validator_.validate(order);
            if (!validation.isValid) {
                logError(order.id, validation.errorMessage);
                continue;
            }

            auto total = pricing_.calculateTotal(order);
            auto [subtotal, tax] = calculateBreakdown(order);

            auto receipt = printer_.generate(order, subtotal, tax, total);
            cout << receipt;

            repository_.save(order.id, total);
        }
    }

private:
    pair<double, double> calculateBreakdown(const Order& order) const {
        double subtotal = 0;
        for (const auto& item : order.items) subtotal += item.total();
        double tax = subtotal * 0.08;
        return {subtotal, tax};
    }

    void logError(const string& orderId, const string& message) {
        cerr << "[ERROR] Order " << orderId << ": " << message << "\n";
    }
};

