// === Strangler Fig Pattern Example ===
// Gradually replacing a legacy payment system

// Legacy interface (can't change — used by many clients)
class LegacyPaymentProcessor {
public:
    virtual ~LegacyPaymentProcessor() = default;
    virtual bool processPayment(const string& cardNumber, double amount) = 0;
    virtual bool refundPayment(const string& transactionId) = 0;
};

// Legacy implementation (buggy, hard to maintain)
class OldPaymentSystem : public LegacyPaymentProcessor {
public:
    bool processPayment(const string& cardNumber, double amount) override {
        // Old, messy implementation with known bugs
        cout << "[LEGACY] Processing payment of $" << amount 
             << " with card ending in " << cardNumber.substr(cardNumber.length() - 4) << "\n";
        return true;  // Always succeeds (bug: doesn't validate)
    }

    bool refundPayment(const string& transactionId) override {
        cout << "[LEGACY] Refunding transaction " << transactionId << "\n";
        return true;
    }
};

// New, clean implementation
class ModernPaymentSystem {
public:
    struct PaymentResult {
        bool success;
        string transactionId;
        string errorMessage;
    };

    PaymentResult charge(const string& token, double amount, const string& currency) {
        // Modern, well-tested implementation
        if (amount <= 0) return {false, "", "Invalid amount"};

        auto txnId = generateTransactionId();
        cout << "[MODERN] Charging $" << amount << " " << currency 
             << " with token " << token << "\n";
        return {true, txnId, ""};
    }

    bool refund(const string& transactionId) {
        cout << "[MODERN] Refunding transaction " << transactionId << "\n";
        return true;
    }

private:
    string generateTransactionId() {
        static atomic<int> counter{0};
        return "TXN-MODERN-" + to_string(++counter);
    }
};

// Strangler: Routes to old or new system based on feature flag
class StranglerPaymentProcessor : public LegacyPaymentProcessor {
    OldPaymentSystem& legacy_;
    ModernPaymentSystem& modern_;
    function<bool(const string&)> useModern_;
    map<string, string> legacyToModernTxn_;

public:
    StranglerPaymentProcessor(OldPaymentSystem& legacy, ModernPaymentSystem& modern,
                               function<bool(const string&)> useModern)
        : legacy_(legacy), modern_(modern), useModern_(move(useModern)) {}

    bool processPayment(const string& cardNumber, double amount) override {
        if (useModern_(cardNumber)) {
            // Route to modern system, but adapt legacy interface
            auto token = "tok_" + cardNumber;  // Tokenize in real implementation
            auto result = modern_.charge(token, amount, "USD");

            if (result.success) {
                // Map modern transaction ID to legacy format for compatibility
                legacyToModernTxn_[cardNumber] = result.transactionId;
            }

            return result.success;
        }

        // Route to legacy system
        return legacy_.processPayment(cardNumber, amount);
    }

    bool refundPayment(const string& transactionId) override {
        // Check if this is a modern transaction
        auto it = find_if(legacyToModernTxn_.begin(), legacyToModernTxn_.end(),
                          [&](const auto& p) { return p.second == transactionId; });

        if (it != legacyToModernTxn_.end()) {
            return modern_.refund(transactionId);
        }

        return legacy_.refundPayment(transactionId);
    }

    double modernTrafficPercentage() const {
        // Analytics to track migration progress
        return 0.0;  // Would calculate from actual traffic
    }
};

// Gradual migration strategy
void demonstrateStranglerFig() {
    OldPaymentSystem legacy;
    ModernPaymentSystem modern;

    // Phase 1: Route 5% of traffic to modern system (canary)
    auto canary = [](const string& card) {
        // Route based on card hash or user segment
        return card.back() == '0';  // 10% of cards
    };

    StranglerPaymentProcessor phase1(legacy, modern, canary);

    cout << "=== Phase 1: Canary (10% modern) ===\n";
    phase1.processPayment("4111111111111110", 100.0);  // Goes to modern
    phase1.processPayment("4111111111111111", 100.0);  // Goes to legacy

    // Phase 2: Route 50% of traffic
    auto halfAndHalf = [](const string& card) {
        return stoll(card) % 2 == 0;
    };

    StranglerPaymentProcessor phase2(legacy, modern, halfAndHalf);

    cout << "\n=== Phase 2: 50/50 Split ===\n";
    phase2.processPayment("4111111111111112", 100.0);  // Modern
    phase2.processPayment("4111111111111113", 100.0);  // Legacy

    // Phase 3: 100% modern, legacy on standby
    auto fullModern = [](const string&) { return true; };

    StranglerPaymentProcessor phase3(legacy, modern, fullModern);

    cout << "\n=== Phase 3: Full Modern ===\n";
    phase3.processPayment("4111111111111114", 100.0);  // Modern
    phase3.processPayment("4111111111111115", 100.0);  // Modern

    // Eventually: Remove strangler, use ModernPaymentSystem directly
    cout << "\n=== Final: Legacy Retired ===\n";
    cout << "ModernPaymentSystem used directly, LegacyPaymentProcessor interface removed\n";
}

int main() {
    demonstrateStranglerFig();
    return 0;
}

