// BEFORE: Hard to extend
class ShippingCalculatorBad {
public:
    double calculate(const string& method, double weight, const string& zip) {
        if (method == "ground") {
            if (zip.starts_with("9")) return weight * 0.50 + 10;  // West coast
            if (zip.starts_with("0")) return weight * 0.60 + 12;  // East coast
            return weight * 0.55 + 11;
        } else if (method == "express") {
            return weight * 1.20 + 25;
        } else if (method == "overnight") {
            return weight * 2.50 + 40;
        }
        return 0;
    }
};

// PREPARATORY REFACTORING: Clean up before adding international
class ShippingMethod {
public:
    virtual ~ShippingMethod() = default;
    virtual string name() const = 0;
    virtual double calculate(double weight, const Address& dest) const = 0;
};

class GroundShipping : public ShippingMethod {
public:
    string name() const override { return "ground"; }

    double calculate(double weight, const Address& dest) const override {
        auto baseRate = getRegionalRate(dest);
        return weight * baseRate.perPound + baseRate.flatFee;
    }

private:
    struct Rate { double perPound; double flatFee; };

    Rate getRegionalRate(const Address& dest) const {
        if (dest.zip.starts_with("9")) return {0.50, 10.0};   // West
        if (dest.zip.starts_with("0")) return {0.60, 12.0};   // East
        return {0.55, 11.0};                                   // Central
    }
};

class ExpressShipping : public ShippingMethod {
public:
    string name() const override { return "express"; }
    double calculate(double weight, const Address&) const override {
        return weight * 1.20 + 25.0;
    }
};

class OvernightShipping : public ShippingMethod {
public:
    string name() const override { return "overnight"; }
    double calculate(double weight, const Address&) const override {
        return weight * 2.50 + 40.0;
    }
};

// NOW adding international is easy — just add a new class
class InternationalShipping : public ShippingMethod {
    string destinationCountry_;

public:
    explicit InternationalShipping(string country) 
        : destinationCountry_(move(country)) {}

    string name() const override { return "international_" + destinationCountry_; }

    double calculate(double weight, const Address&) const override {
        auto baseRate = getCountryRate(destinationCountry_);
        auto customsFee = weight > 10 ? 25.0 : 10.0;
        return weight * baseRate + 35.0 + customsFee;  // Base + handling + customs
    }

private:
    double getCountryRate(const string& country) const {
        static const map<string, double> rates = {
            {"CA", 2.0}, {"MX", 2.5}, {"UK", 3.0}, {"DE", 3.0}, {"JP", 4.0}
        };
        auto it = rates.find(country);
        return it != rates.end() ? it->second : 5.0;  // Default for other countries
    }
};

class ShippingCalculator {
    map<string, unique_ptr<ShippingMethod>> methods_;

public:
    ShippingCalculator() {
        registerMethod(make_unique<GroundShipping>());
        registerMethod(make_unique<ExpressShipping>());
        registerMethod(make_unique<OvernightShipping>());
    }

    void registerMethod(unique_ptr<ShippingMethod> method) {
        methods_[method->name()] = move(method);
    }

    double calculate(const string& methodName, double weight, const Address& dest) {
        auto it = methods_.find(methodName);
        if (it == methods_.end()) {
            throw invalid_argument("Unknown shipping method: " + methodName);
        }
        return it->second->calculate(weight, dest);
    }
};

