// COMPREHENSION REFACTORING: Rename and restructure as we read
// After analysis: finds first contiguous subarray summing to target

struct SubarrayFinder {
    // Finds the first contiguous subarray that sums to target
    // Returns the subarray, or empty if none exists
    vector<int> findFirstSubarrayWithSum(const vector<int>& numbers, int targetSum) {
        for (size_t start = 0; start < numbers.size(); ++start) {
            for (size_t end = start; end < numbers.size(); ++end) {
                auto currentSum = calculateSum(numbers, start, end);

                if (currentSum == targetSum) {
                    return extractSubarray(numbers, start, end);
                }
            }
        }
        return {};  // No subarray found
    }

private:
    int calculateSum(const vector<int>& numbers, size_t start, size_t end) {
        int sum = 0;
        for (size_t i = start; i <= end; ++i) {
            sum += numbers[i];
        }
        return sum;
    }

    vector<int> extractSubarray(const vector<int>& numbers, size_t start, size_t end) {
        return vector<int>(numbers.begin() + start, numbers.begin() + end + 1);
    }
};

// Further improvement: O(n) sliding window instead of O(n³)
struct OptimizedSubarrayFinder {
    vector<int> findFirstSubarrayWithSum(const vector<int>& numbers, int targetSum) {
        unordered_map<int, size_t> prefixSumToIndex;
        prefixSumToIndex[0] = 0;  // Sum of zero elements

        int currentSum = 0;
        for (size_t i = 0; i < numbers.size(); ++i) {
            currentSum += numbers[i];

            auto needed = currentSum - targetSum;
            auto it = prefixSumToIndex.find(needed);
            if (it != prefixSumToIndex.end()) {
                return vector<int>(numbers.begin() + it->second, numbers.begin() + i + 1);
            }

            prefixSumToIndex[currentSum] = i + 1;
        }

        return {};
    }
};

