int main() {
    cout << "=== Preparatory Refactoring Result ===\n";

    ShippingCalculator calculator;
    calculator.registerMethod(make_unique<InternationalShipping>("UK"));

    Address usAddress{"90210", "US"};
    Address ukAddress{"SW1A", "UK"};

    cout << "Ground to LA: $" << calculator.calculate("ground", 5.0, usAddress) << "\n";
    cout << "Express to LA: $" << calculator.calculate("express", 5.0, usAddress) << "\n";
    cout << "International to UK: $" << calculator.calculate("international_UK", 5.0, ukAddress) << "\n";

    cout << "\n=== Comprehension Refactoring Result ===\n";

    vector<int> numbers = {1, 4, 20, 3, 10, 5};
    int target = 33;  // 20 + 3 + 10 = 33

    SubarrayFinder finder;
    auto result = finder.findFirstSubarrayWithSum(numbers, target);

    cout << "Subarray summing to " << target << ": ";
    for (int n : result) cout << n << " ";
    cout << "\n";

    OptimizedSubarrayFinder fastFinder;
    auto fastResult = fastFinder.findFirstSubarrayWithSum(numbers, target);
    assert(result == fastResult);
    cout << "Optimized version produces same result\n";

    return 0;
}

