// === Characterization Tests: Documenting behavior before refactoring ===

// Legacy code we need to refactor but don't fully understand
class LegacyDiscountEngine {
public:
    double calc(double amt, int yrs, string tp) {
        double d = 0;
        if (tp == "VIP") {
            if (yrs > 5) d = 0.25;
            else if (yrs > 2) d = 0.20;
            else d = 0.15;
        } else if (tp == "LOYAL") {
            if (yrs > 3) d = 0.10;
            else if (amt > 500) d = 0.05;
        } else {
            if (amt > 1000) d = 0.05;
        }
        if (amt > 2000 && d < 0.20) d += 0.05;
        return amt * (1 - d);
    }
};

// Step 1: Write characterization tests to lock in behavior
class LegacyDiscountEngineCharacterizationTests {
public:
    void runAll() {
        testVipDiscounts();
        testLoyalDiscounts();
        testStandardDiscounts();
        testBonusThreshold();
        cout << "All characterization tests passed — behavior locked!\n";
    }

private:
    LegacyDiscountEngine engine_;

    void testVipDiscounts() {
        // VIP, > 5 years: 25% off
        assert(engine_.calc(100, 6, "VIP") == 75.0);
        // VIP, 3-5 years: 20% off
        assert(engine_.calc(100, 4, "VIP") == 80.0);
        // VIP, < 3 years: 15% off
        assert(engine_.calc(100, 1, "VIP") == 85.0);
    }

    void testLoyalDiscounts() {
        // LOYAL, > 3 years: 10% off
        assert(engine_.calc(100, 4, "LOYAL") == 90.0);
        // LOYAL, <= 3 years, > $500: 5% off
        assert(engine_.calc(600, 1, "LOYAL") == 570.0);
        // LOYAL, <= 3 years, <= $500: no discount
        assert(engine_.calc(100, 1, "LOYAL") == 100.0);
    }

    void testStandardDiscounts() {
        // Standard, > $1000: 5% off
        assert(engine_.calc(2000, 0, "STANDARD") == 1900.0);
        // Standard, <= $1000: no discount
        assert(engine_.calc(500, 0, "STANDARD") == 500.0);
    }

    void testBonusThreshold() {
        // Amount > $2000 with discount < 20% gets extra 5%
        // LOYAL, 4 years: 10% + 5% bonus = 15% off
        assert(engine_.calc(2500, 4, "LOYAL") == 2500 * 0.85);
        // VIP, 6 years: already 25%, no bonus (would exceed)
        assert(engine_.calc(2500, 6, "VIP") == 2500 * 0.75);
    }
};

// Step 2: Refactor with safety net in place
class DiscountEngine {
public:
    double calculateFinalPrice(double amount, int years, const string& customerType) {
        auto baseDiscount = calculateBaseDiscount(amount, years, customerType);
        auto bonusDiscount = calculateBonusDiscount(amount, baseDiscount);
        auto totalDiscount = min(baseDiscount + bonusDiscount, 0.30);  // Cap at 30%

        return amount * (1.0 - totalDiscount);
    }

private:
    double calculateBaseDiscount(double amount, int years, const string& type) {
        if (type == "VIP") return calculateVipDiscount(years);
        if (type == "LOYAL") return calculateLoyalDiscount(amount, years);
        return calculateStandardDiscount(amount);
    }

    double calculateVipDiscount(int years) {
        if (years > 5) return 0.25;
        if (years > 2) return 0.20;
        return 0.15;
    }

    double calculateLoyalDiscount(double amount, int years) {
        if (years > 3) return 0.10;
        if (amount > 500) return 0.05;
        return 0.0;
    }

    double calculateStandardDiscount(double amount) {
        if (amount > 1000) return 0.05;
        return 0.0;
    }

    double calculateBonusDiscount(double amount, double baseDiscount) {
        if (amount > 2000 && baseDiscount < 0.20) return 0.05;
        return 0.0;
    }
};

// Step 3: Verify refactored code matches characterization tests
class RefactoredDiscountEngineTests {
public:
    void runAll() {
        testVipDiscounts();
        testLoyalDiscounts();
        testStandardDiscounts();
        testBonusThreshold();
        cout << "Refactored engine passes all characterization tests!\n";
    }

private:
    DiscountEngine engine_;

    void testVipDiscounts() {
        assert(engine_.calculateFinalPrice(100, 6, "VIP") == 75.0);
        assert(engine_.calculateFinalPrice(100, 4, "VIP") == 80.0);
        assert(engine_.calculateFinalPrice(100, 1, "VIP") == 85.0);
    }

    void testLoyalDiscounts() {
        assert(engine_.calculateFinalPrice(100, 4, "LOYAL") == 90.0);
        assert(engine_.calculateFinalPrice(600, 1, "LOYAL") == 570.0);
        assert(engine_.calculateFinalPrice(100, 1, "LOYAL") == 100.0);
    }

    void testStandardDiscounts() {
        assert(engine_.calculateFinalPrice(2000, 0, "STANDARD") == 1900.0);
        assert(engine_.calculateFinalPrice(500, 0, "STANDARD") == 500.0);
    }

    void testBonusThreshold() {
        assert(engine_.calculateFinalPrice(2500, 4, "LOYAL") == 2500 * 0.85);
        assert(engine_.calculateFinalPrice(2500, 6, "VIP") == 2500 * 0.75);
    }
};

// === Small, safe refactoring steps demonstrated ===

class RefactoringDemo {
public:
    // Step 1: Original messy function
    double calculateOriginal(double price, int qty, string cust, bool express) {
        double t = price * qty;
        if (cust == "VIP") t *= 0.9;
        else if (cust == "LOYAL") t *= 0.95;
        if (express) t += 25;
        else t += 10;
        return t;
    }

    // Step 2: Extract variables for clarity
    double calculateStep2(double price, int qty, string cust, bool express) {
        double subtotal = price * qty;

        double customerDiscount = 1.0;
        if (cust == "VIP") customerDiscount = 0.9;
        else if (cust == "LOYAL") customerDiscount = 0.95;

        double discountedSubtotal = subtotal * customerDiscount;

        double shippingCost = express ? 25 : 10;

        return discountedSubtotal + shippingCost;
    }

    // Step 3: Extract methods
    double calculateStep3(double price, int qty, string cust, bool express) {
        auto subtotal = calculateSubtotal(price, qty);
        auto discounted = applyCustomerDiscount(subtotal, cust);
        auto shipping = calculateShipping(express);
        return discounted + shipping;
    }

    // Step 4: Replace conditionals with polymorphism (if more types added)
    double calculateStep4(double price, int qty, const Customer& customer, bool express) {
        auto subtotal = calculateSubtotal(price, qty);
        auto discounted = customer.applyDiscount(subtotal);
        auto shipping = calculateShipping(express);
        return discounted + shipping;
    }

private:
    double calculateSubtotal(double price, int qty) {
        return price * qty;
    }

    double applyCustomerDiscount(double amount, const string& cust) {
        if (cust == "VIP") return amount * 0.9;
        if (cust == "LOYAL") return amount * 0.95;
        return amount;
    }

    double calculateShipping(bool express) {
        return express ? 25.0 : 10.0;
    }

    struct Customer {
        virtual double applyDiscount(double amount) const { return amount; }
    };
};

int main() {
    cout << "=== Characterization Tests ===\n";
    LegacyDiscountEngineCharacterizationTests charTests;
    charTests.runAll();

    cout << "\n=== Refactored Engine Tests ===\n";
    RefactoredDiscountEngineTests refactoredTests;
    refactoredTests.runAll();

    cout << "\n=== Refactoring Steps Demo ===\n";
    RefactoringDemo demo;

    // All steps produce same result
    assert(demo.calculateOriginal(100, 2, "VIP", true) == 
           demo.calculateStep2(100, 2, "VIP", true));
    assert(demo.calculateStep2(100, 2, "VIP", true) == 
           demo.calculateStep3(100, 2, "VIP", true));

    cout << "All refactoring steps preserve behavior!\n";

    return 0;
}

