// Extract Method with local variables
class InvoiceGenerator {
public:
    string generate(const Order& order) {
        // BEFORE: Inline calculation
        auto result = "Invoice for " + order.customerName + "\n";

        double subtotal = 0;
        for (const auto& item : order.items) {
            subtotal += item.price * item.quantity;
        }
        result += "Subtotal: $" + to_string(subtotal) + "\n";

        double tax = subtotal * getTaxRate(order.shippingState);
        result += "Tax: $" + to_string(tax) + "\n";

        double shipping = order.items.size() * 5.0;
        if (order.expressShipping) shipping += 15.0;
        result += "Shipping: $" + to_string(shipping) + "\n";

        double total = subtotal + tax + shipping;
        result += "Total: $" + to_string(total) + "\n";

        return result;
    }

    // AFTER: Extracted methods with return values
    string generateClean(const Order& order) {
        auto result = "Invoice for " + order.customerName + "\n";

        auto subtotal = calculateSubtotal(order);
        auto tax = calculateTax(subtotal, order.shippingState);
        auto shipping = calculateShipping(order);
        auto total = calculateTotal(subtotal, tax, shipping);

        result += formatLine("Subtotal", subtotal);
        result += formatLine("Tax", tax);
        result += formatLine("Shipping", shipping);
        result += formatLine("Total", total);

        return result;
    }

private:
    double calculateSubtotal(const Order& order) {
        return transform_reduce(order.items.begin(), order.items.end(), 0.0, plus<>(),
                                [](const auto& item) { return item.price * item.quantity; });
    }

    double calculateTax(double subtotal, const string& state) {
        return subtotal * getTaxRate(state);
    }

    double calculateShipping(const Order& order) {
        auto base = order.items.size() * 5.0;
        return order.expressShipping ? base + 15.0 : base;
    }

    double calculateTotal(double subtotal, double tax, double shipping) {
        return subtotal + tax + shipping;
    }

    string formatLine(const string& label, double amount) {
        ostringstream oss;
        oss << label << ": $" << fixed << setprecision(2) << amount << "\n";
        return oss.str();
    }

    double getTaxRate(const string& state) {
        static const map<string, double> rates = {
            {"CA", 0.0725}, {"NY", 0.08}, {"TX", 0.0625}
        };
        auto it = rates.find(state);
        return it != rates.end() ? it->second : 0.05;
    }
};

