           customer.debtToIncome < 0.36 &&
           customer.employmentYears >= 2 &&
           customer.accountAge > 365 * 2;
}

// AFTER: Named intermediate values reveal intent
bool isEligibleForLoan(const Customer& customer) {
    auto hasMinimumIncome = customer.income > MINIMUM_INCOME;
    auto hasGoodCredit = customer.creditScore > GOOD_CREDIT_THRESHOLD;
    auto hasLowDebtRatio = customer.debtToIncome < MAX_DEBT_TO_INCOME;
    auto hasStableEmployment = customer.employmentYears >= MIN_EMPLOYMENT_YEARS;
    auto hasEstablishedAccount = customer.accountAge > MIN_ACCOUNT_AGE_DAYS;

    return hasMinimumIncome && 
           hasGoodCredit && 
           hasLowDebtRatio && 
           hasStableEmployment && 
           hasEstablishedAccount;
}

