// BEFORE: Complex method with many locals that resist extraction
class Account {
    vector<Transaction> transactions_;

public:
    // This method is too complex to extract easily
    double complexCalculationBad(int startYear, int endYear, 
                                  string category, bool includePending,
                                  double minAmount, double exchangeRate) {
        double total = 0;
        int count = 0;
        double maxTransaction = 0;
        string mostFrequentMerchant;
        map<string, int> merchantFrequency;

        for (const auto& txn : transactions_) {
            if (txn.year < startYear || txn.year > endYear) continue;
            if (txn.category != category) continue;
            if (!includePending && txn.status == "PENDING") continue;
            if (abs(txn.amount) < minAmount) continue;

            auto convertedAmount = txn.amount * exchangeRate;
            total += convertedAmount;
            count++;

            if (abs(convertedAmount) > maxTransaction) {
                maxTransaction = abs(convertedAmount);
            }

            merchantFrequency[txn.merchant]++;
        }

        // Find most frequent merchant
        int maxFreq = 0;
        for (const auto& [merchant, freq] : merchantFrequency) {
            if (freq > maxFreq) {
                maxFreq = freq;
                mostFrequentMerchant = merchant;
            }
        }

        // Apply bonus for frequent merchant
        if (mostFrequentMerchant == "PreferredVendor") {
            total *= 0.95;
        }

        // Calculate average and return adjusted total
        auto average = (count > 0) ? total / count : 0;
        return total - (average * 0.1);  // Small penalty for low average
    }

    // AFTER: Method object
    double complexCalculation(int startYear, int endYear,
                               string category, bool includePending,
                               double minAmount, double exchangeRate) {
        return AccountCalculator(*this, startYear, endYear, move(category),
                                  includePending, minAmount, exchangeRate)
               .compute();
    }

private:
    struct Transaction {
        int year;
        string category;
        string status;
        double amount;
        string merchant;
    };

    // Method object: turns complex method into a class
    class AccountCalculator {
        const Account& account_;
        int startYear_;
        int endYear_;
        string category_;
        bool includePending_;
        double minAmount_;
        double exchangeRate_;

        // Result accumulators
        double total_ = 0;
        int count_ = 0;
        double maxTransaction_ = 0;
        string mostFrequentMerchant_;
        map<string, int> merchantFrequency_;

    public:
        AccountCalculator(const Account& account, int startYear, int endYear,
                          string category, bool includePending,
                          double minAmount, double exchangeRate)
            : account_(account), startYear_(startYear), endYear_(endYear),
              category_(move(category)), includePending_(includePending),
              minAmount_(minAmount), exchangeRate_(exchangeRate) {}

        double compute() {
            filterAndAccumulateTransactions();
            findMostFrequentMerchant();
            applyMerchantBonus();
            return calculateFinalResult();
        }

    private:
        void filterAndAccumulateTransactions() {
            for (const auto& txn : account_.transactions_) {
                if (!matchesCriteria(txn)) continue;

                auto convertedAmount = txn.amount * exchangeRate_;
                accumulateTransaction(txn, convertedAmount);
            }
        }

        bool matchesCriteria(const Transaction& txn) const {
            if (txn.year < startYear_ || txn.year > endYear_) return false;
            if (txn.category != category_) return false;
            if (!includePending_ && txn.status == "PENDING") return false;
            if (abs(txn.amount) < minAmount_) return false;
            return true;
        }

        void accumulateTransaction(const Transaction& txn, double convertedAmount) {
            total_ += convertedAmount;
            count_++;

            if (abs(convertedAmount) > maxTransaction_) {
                maxTransaction_ = abs(convertedAmount);
            }

            merchantFrequency_[txn.merchant]++;
        }

        void findMostFrequentMerchant() {
            int maxFreq = 0;
            for (const auto& [merchant, freq] : merchantFrequency_) {
                if (freq > maxFreq) {
                    maxFreq = freq;
                    mostFrequentMerchant_ = merchant;
                }
            }
        }

        void applyMerchantBonus() {
            if (mostFrequentMerchant_ == "PreferredVendor") {
                total_ *= 0.95;
            }
        }

        double calculateFinalResult() const {
            auto average = (count_ > 0) ? total_ / count_ : 0;
            return total_ - (average * 0.1);
        }
    };

    friend class AccountCalculator;
};

// === Another Method Object example: Complex algorithm ===

class ReportGenerator {
public:
    string generateComplexReport(const DataSet& data, const Config& config) {
        return ReportCalculation(data, config).generate();
    }

private:
    struct DataSet { vector<double> values; };
    struct Config { bool normalize; double threshold; };

    class ReportCalculation {
        const DataSet& data_;
        const Config& config_;

        double mean_ = 0;
        double stdDev_ = 0;
        vector<double> filtered_;
        string report_;

    public:
        ReportCalculation(const DataSet& data, const Config& config)
            : data_(data), config_(config) {}

        string generate() {
            calculateStatistics();
            filterOutliers();
            buildReport();
            return report_;
        }

    private:
        void calculateStatistics() {
            mean_ = accumulate(data_.values.begin(), data_.values.end(), 0.0) 
                    / data_.values.size();

            double variance = 0;
            for (auto v : data_.values) {
                variance += pow(v - mean_, 2);
            }
            variance /= data_.values.size();
            stdDev_ = sqrt(variance);
        }

        void filterOutliers() {
            for (auto v : data_.values) {
                auto zScore = abs(v - mean_) / stdDev_;
                if (zScore <= config_.threshold) {
                    filtered_.push_back(v);
                }
            }
        }

        void buildReport() {
            ostringstream oss;
            oss << "Report Summary\n";
            oss << "==============\n";
            oss << "Total samples: " << data_.values.size() << "\n";
            oss << "After filtering: " << filtered_.size() << "\n";
            oss << "Mean: " << mean_ << "\n";
            oss << "StdDev: " << stdDev_ << "\n";

            if (config_.normalize) {
                oss << "Normalized values:\n";
                for (auto v : filtered_) {
                    oss << "  " << (v - mean_) / stdDev_ << "\n";
                }
            }

            report_ = oss.str();
        }
    };
};

