// When you can't modify a class but need a method on it
// Use a free function (C++ style) instead of subclassing

// External library class — can't modify
namespace ExternalLibrary {
    class Date {
        int year_, month_, day_;
    public:
        Date(int y, int m, int d) : year_(y), month_(m), day_(d) {}
        int year() const { return year_; }
        int month() const { return month_; }
        int day() const { return day_; }
    };
}

// Foreign method — extends Date without modifying it
namespace ExternalLibrary {
    // C++ allows ADL-friendly extensions in the same namespace
    Date nextDay(const Date& date) {
        // Simplified — real implementation handles month/year boundaries
        return Date(date.year(), date.month(), date.day() + 1);
    }

    bool isLeapYear(const Date& date) {
        auto year = date.year();
        return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    }

    int dayOfYear(const Date& date) {
        static const int daysBeforeMonth[] = {0, 0, 31, 59, 90, 120, 151, 
                                               181, 212, 243, 273, 304, 334};
        auto dayOfYear = daysBeforeMonth[date.month()] + date.day();
        if (date.month() > 2 && isLeapYear(date)) dayOfYear++;
        return dayOfYear;
    }
}

// === Introduce Local Extension ===

// When you need many foreign methods, create a wrapper or subclass
class DateTimeExtended {
    chrono::system_clock::time_point timePoint_;

public:
    explicit DateTimeExtended(chrono::system_clock::time_point tp) : timePoint_(tp) {}

    static DateTimeExtended now() {
        return DateTimeExtended(chrono::system_clock::now());
    }

    static DateTimeExtended fromYMD(int year, int month, int day) {
        tm timeinfo = {};
        timeinfo.tm_year = year - 1900;
        timeinfo.tm_mon = month - 1;
        timeinfo.tm_mday = day;
        auto time = mktime(&timeinfo);
        return DateTimeExtended(chrono::system_clock::from_time_t(time));
    }

    // Extended functionality
    bool isWeekend() const {
        auto time = chrono::system_clock::to_time_t(timePoint_);
        auto* local = localtime(&time);
        return local->tm_wday == 0 || local->tm_wday == 6;
    }

    bool isBusinessDay() const {
        return !isWeekend();
    }

    DateTimeExtended startOfMonth() const {
        auto time = chrono::system_clock::to_time_t(timePoint_);
        auto* local = localtime(&time);
        local->tm_mday = 1;
        local->tm_hour = 0;
        local->tm_min = 0;
        local->tm_sec = 0;
        return DateTimeExtended(chrono::system_clock::from_time_t(mktime(local)));
    }

    DateTimeExtended addDays(int days) const {
        return DateTimeExtended(timePoint_ + chrono::days(days));
    }

    int daysUntil(const DateTimeExtended& other) const {
        return chrono::duration_cast<chrono::days>(other.timePoint_ - timePoint_).count();
    }

    string toString() const {
        auto time = chrono::system_clock::to_time_t(timePoint_);
        auto* local = localtime(&time);
        ostringstream oss;
        oss << put_time(local, "%Y-%m-%d %H:%M:%S");
        return oss.str();
    }

    // Access to underlying
    chrono::system_clock::time_point underlying() const { return timePoint_; }
};

int main() {
    cout << "=== Hide Delegate Demo ===\n";

    Employee mgr("Bob", nullptr);
    Department eng("ENG-001", &mgr);
    Employee alice("Alice", &eng);

    clientCode(alice);

    cout << "\n=== Foreign Method Demo ===\n";
    ExternalLibrary::Date date(2024, 3, 15);
    cout << "Date: " << date.year() << "-" << date.month() << "-" << date.day() << "\n";
    cout << "Day of year: " << ExternalLibrary::dayOfYear(date) << "\n";
    cout << "Is leap year: " << (ExternalLibrary::isLeapYear(date) ? "yes" : "no") << "\n";

    cout << "\n=== Local Extension Demo ===\n";
    auto today = DateTimeExtended::now();
    cout << "Today: " << today.toString() << "\n";
    cout << "Is business day: " << (today.isBusinessDay() ? "yes" : "no") << "\n";

    auto nextWeek = today.addDays(7);
    cout << "Next week: " << nextWeek.toString() << "\n";
    cout << "Days until: " << today.daysUntil(nextWeek) << "\n";

    return 0;
}

