// AFTER: Phone number as rich type
class PhoneNumber {
    string countryCode_;
    string areaCode_;
    string number_;

public:
    PhoneNumber(string country, string area, string number)
        : countryCode_(move(country)), areaCode_(move(area)), number_(move(number)) {
        validate();
    }

    static PhoneNumber parse(const string& raw) {
        // Parse formats like "+1-555-123-4567" or "(555) 123-4567"
        regex intl(R"(^\+(\d{1,3})-(\d{3})-(\d{3})-(\d{4})$)");
        regex domestic(R"(^\((\d{3})\)\s*(\d{3})-(\d{4})$)");

        smatch match;
        if (regex_match(raw, match, intl)) {
            return PhoneNumber(match[1], match[2], match[3] + "-" + string(match[4]));
        }
        if (regex_match(raw, match, domestic)) {
            return PhoneNumber("1", match[1], match[2] + "-" + string(match[3]));
        }
        throw invalid_argument("Invalid phone format: " + raw);
    }

    string formatInternational() const {
        return "+" + countryCode_ + "-" + areaCode_ + "-" + number_;
    }

    string formatDomestic() const {
        return "(" + areaCode_ + ") " + number_;
    }

    bool isTollFree() const {
        return areaCode_.starts_with("8");
    }

    bool operator==(const PhoneNumber& other) const {
        return countryCode_ == other.countryCode_ &&
               areaCode_ == other.areaCode_ &&
               number_ == other.number_;
    }

private:
    void validate() {
        if (countryCode_.empty() || areaCode_.empty() || number_.empty()) {
            throw invalid_argument("Phone number components cannot be empty");
        }
    }
};

