// AFTER: Money as value object
class Money {
    double amount_;
    string currency_;

public:
    Money(double amount, string currency)
        : amount_(amount), currency_(move(currency)) {
        if (amount_ < 0) throw invalid_argument("Money cannot be negative");
    }

    static Money zero(string currency) { return Money(0, move(currency)); }
    static Money usd(double amount) { return Money(amount, "USD"); }
    static Money eur(double amount) { return Money(amount, "EUR"); }

    double amount() const { return amount_; }
    const string& currency() const { return currency_; }

    Money add(const Money& other) const {
        assertSameCurrency(other);
        return Money(amount_ + other.amount_, currency_);
    }

    Money subtract(const Money& other) const {
        assertSameCurrency(other);
        if (other.amount_ > amount_) {
            throw invalid_argument("Insufficient funds");
        }
        return Money(amount_ - other.amount_, currency_);
    }

    Money multiply(double factor) const {
        return Money(amount_ * factor, currency_);
    }

    bool isZero() const { return amount_ == 0; }
    bool isGreaterThan(const Money& other) const {
        assertSameCurrency(other);
        return amount_ > other.amount_;
    }

    string toString() const {
        ostringstream oss;
        oss << currency_ << " " << fixed << setprecision(2) << amount_;
        return oss.str();
    }

    bool operator==(const Money& other) const {
        return amount_ == other.amount_ && currency_ == other.currency_;
    }

private:
    void assertSameCurrency(const Money& other) const {
        if (currency_ != other.currency_) {
            throw invalid_argument("Cannot operate on different currencies");
        }
    }
};

class Account {
    Money balance_;

public:
    explicit Account(Money initialBalance) : balance_(move(initialBalance)) {}

    void deposit(const Money& amount) {
        balance_ = balance_.add(amount);
    }

    void withdraw(const Money& amount) {
        balance_ = balance_.subtract(amount);
    }

    const Money& balance() const { return balance_; }
    bool isOverdrawn() const { return balance_.isZero(); }
};

