// === Registry pattern for reference management ===

class CustomerRegistry {
    map<string, weak_ptr<Customer>> customers_;

public:
    shared_ptr<Customer> getOrCreate(const string& email, 
                                      const string& name, 
                                      const string& address) {
        auto it = customers_.find(email);
        if (it != customers_.end()) {
            if (auto existing = it->second.lock()) {
                return existing;  // Return existing customer
            }
        }

        auto customer = make_shared<Customer>(name, email, address);
        customers_[email] = customer;
        return customer;
    }
};

