// AFTER: Named constants
namespace PhysicsConstants {
    constexpr double PI = 3.14159265358979323846;
    constexpr double EARTH_GM = 398600.4418;  // km³/s² — Standard gravitational parameter
    constexpr double EARTH_RADIUS_KM = 6371.0;
}

namespace TemperatureConversion {
    constexpr double CELSIUS_TO_FAHRENHEIT_RATIO = 9.0 / 5.0;
    constexpr double FAHRENHEIT_OFFSET = 32.0;
}

namespace TimeConstants {
    constexpr int SECONDS_PER_MINUTE = 60;
    constexpr int MINUTES_PER_HOUR = 60;
    constexpr int HOURS_PER_DAY = 24;
    constexpr int SECONDS_PER_HOUR = SECONDS_PER_MINUTE * MINUTES_PER_HOUR;
    constexpr int SECONDS_PER_DAY = SECONDS_PER_HOUR * HOURS_PER_DAY;
}

class PhysicsEngine {
public:
    double calculateOrbitalPeriod(double radiusKm) {
        using namespace PhysicsConstants;
        return 2 * PI * sqrt(pow(radiusKm, 3) / EARTH_GM);
    }

    double celsiusToFahrenheit(double celsius) {
        using namespace TemperatureConversion;
        return celsius * CELSIUS_TO_FAHRENHEIT_RATIO + FAHRENHEIT_OFFSET;
    }

    string formatDuration(int totalSeconds) {
        using namespace TimeConstants;

        auto hours = totalSeconds / SECONDS_PER_HOUR;
        auto remaining = totalSeconds % SECONDS_PER_HOUR;
        auto minutes = remaining / SECONDS_PER_MINUTE;
        auto seconds = remaining % SECONDS_PER_MINUTE;

        ostringstream oss;
        oss << setw(2) << setfill('0') << hours << ":"
            << setw(2) << setfill('0') << minutes << ":"
            << setw(2) << setfill('0') << seconds;
        return oss.str();
    }

    double calculateEscapeVelocity(double massKg, double radiusM) {
        constexpr double GRAVITATIONAL_CONSTANT = 6.67430e-11;  // m³ kg⁻¹ s⁻²
        return sqrt(2 * GRAVITATIONAL_CONSTANT * massKg / radiusM);
    }
};

// === Encapsulate Collection ===

// BEFORE: Internal collection exposed
class TeamBad {
public:
    vector<string> members;  // Public! Anyone can modify
};

// AFTER: Collection encapsulated
class Team {
    vector<string> members_;
    string name_;

public:
    explicit Team(string name) : name_(move(name)) {}

    void addMember(const string& member) {
        if (find(members_.begin(), members_.end(), member) != members_.end()) {
            throw invalid_argument("Member already exists: " + member);
        }
        members_.push_back(member);
    }

    void removeMember(const string& member) {
        auto it = find(members_.begin(), members_.end(), member);
        if (it == members_.end()) {
            throw invalid_argument("Member not found: " + member);
        }
        members_.erase(it);
    }

    bool hasMember(const string& member) const {
        return find(members_.begin(), members_.end(), member) != members_.end();
    }

    size_t memberCount() const { return members_.size(); }

    // Return read-only view
    const vector<string>& members() const { return members_; }

    // Or return iterator pair for safe traversal
    auto begin() const { return members_.begin(); }
    auto end() const { return members_.end(); }
};

