    cout << "=== Replace Array with Object ===\n";
    EmployeeDatabase db;
    db.addEmployee(EmployeeRecord("Alice", 30, 75000, "Engineering"));
    db.addEmployee(EmployeeRecord("Bob", 25, 60000, "Sales"));
    db.addEmployee(EmployeeRecord("Carol", 35, 90000, "Engineering"));

    auto engineers = db.findByDepartment("Engineering");
    cout << "Engineers:\n";
    for (const auto& e : engineers) {
        cout << "  " << e.name() << ", $" << e.salary() << "\n";
    }
    cout << "Total payroll: $" << db.totalPayroll() << "\n";

    cout << "\n=== Replace Magic Numbers ===\n";
    PhysicsEngine physics;
    cout << "Orbital period at 7000km: " << physics.calculateOrbitalPeriod(7000) << " seconds\n";
    cout << "100°C = " << physics.celsiusToFahrenheit(100) << "°F\n";
    cout << "3661 seconds = " << physics.formatDuration(3661) << "\n";

    cout << "\n=== Encapsulate Collection ===\n";
    Team team("Alpha");
    team.addMember("Alice");
    team.addMember("Bob");
    cout << "Team " << team.memberCount() << " members:\n";
    for (const auto& m : team) {
        cout << "  " << m << "\n";
    }

    return 0;
}
